import React, { useState } from 'react';
import { QpcrConfig } from '../../types';
import { Settings, Plus, Trash2 } from 'lucide-react';

interface Props {
  initialConfig: QpcrConfig;
  onNext: (config: QpcrConfig) => void;
}

export const QpcrConfigForm: React.FC<Props> = ({ initialConfig, onNext }) => {
  const [config, setConfig] = useState<QpcrConfig>(initialConfig);
  const [newGroup, setNewGroup] = useState('');
  const [newGene, setNewGene] = useState('');

  const addGroup = () => {
    if (newGroup && !config.groups.includes(newGroup)) {
      setConfig(prev => ({ ...prev, groups: [...prev.groups, newGroup] }));
      setNewGroup('');
    }
  };

  const removeGroup = (g: string) => {
    if (config.groups.length <= 1) return; // Prevent deleting last group
    setConfig(prev => ({
      ...prev,
      groups: prev.groups.filter(x => x !== g),
      controlGroup: prev.controlGroup === g ? prev.groups.find(x => x !== g) || '' : prev.controlGroup
    }));
  };

  const addGene = () => {
    if (newGene && !config.targetGenes.includes(newGene)) {
      setConfig(prev => ({ ...prev, targetGenes: [...prev.targetGenes, newGene] }));
      setNewGene('');
    }
  };

  const removeGene = (g: string) => {
    if (config.targetGenes.length <= 1) return;
    setConfig(prev => ({ ...prev, targetGenes: prev.targetGenes.filter(x => x !== g) }));
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 max-w-4xl mx-auto">
      <div className="flex items-center gap-3 mb-6 border-b border-slate-100 pb-4">
        <div className="bg-blue-100 p-2 rounded-lg text-blue-600">
          <Settings size={24} />
        </div>
        <div>
          <h2 className="text-xl font-bold text-slate-800">实验参数设置</h2>
          <p className="text-sm text-slate-500">定义您的实验分组和基因信息</p>
        </div>
      </div>

      <div className="grid md:grid-cols-2 gap-8">
        {/* Left Column: General & Groups */}
        <div className="space-y-6">
          {/* Replicates */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">生物学重复数 (n)</label>
            <input
              type="number"
              min={1}
              max={20}
              value={config.replicates}
              onChange={(e) => setConfig({ ...config, replicates: parseInt(e.target.value) || 3 })}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-science-500 focus:border-transparent transition-all"
            />
          </div>

          {/* Reference Gene */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">内参基因名称 (Reference Gene)</label>
            <input
              type="text"
              value={config.referenceGene}
              onChange={(e) => setConfig({ ...config, referenceGene: e.target.value })}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-science-500 focus:border-transparent transition-all"
            />
          </div>

          {/* Groups Management */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">实验分组</label>
            <div className="flex gap-2 mb-3">
              <input
                type="text"
                placeholder="添加分组 (如: Treatment A)"
                value={newGroup}
                onChange={(e) => setNewGroup(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addGroup()}
                className="flex-1 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-science-500 outline-none"
              />
              <button 
                onClick={addGroup}
                className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 rounded-lg transition-colors"
              >
                <Plus size={20} />
              </button>
            </div>
            <div className="space-y-2 max-h-48 overflow-y-auto">
              {config.groups.map(group => (
                <div key={group} className="flex items-center justify-between bg-slate-50 px-3 py-2 rounded-lg border border-slate-100">
                  <span className="text-sm font-medium text-slate-700">{group}</span>
                  <button 
                    onClick={() => removeGroup(group)}
                    className="text-slate-400 hover:text-red-500 transition-colors"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>

        {/* Right Column: Control & Targets */}
        <div className="space-y-6">
           {/* Control Selector */}
           <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">对照组 (Control Group)</label>
            <select
              value={config.controlGroup}
              onChange={(e) => setConfig({ ...config, controlGroup: e.target.value })}
              className="w-full px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-science-500 focus:border-transparent bg-white"
            >
              {config.groups.map(g => (
                <option key={g} value={g}>{g}</option>
              ))}
            </select>
            <p className="text-xs text-slate-500 mt-1">用于 ΔΔCt 计算的基准组</p>
          </div>

          {/* Target Genes */}
          <div>
            <label className="block text-sm font-medium text-slate-700 mb-2">目的基因列表 (Target Genes)</label>
            <div className="flex gap-2 mb-3">
              <input
                type="text"
                placeholder="添加基因 (如: IL-6)"
                value={newGene}
                onChange={(e) => setNewGene(e.target.value)}
                onKeyDown={(e) => e.key === 'Enter' && addGene()}
                className="flex-1 px-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-science-500 outline-none"
              />
              <button 
                onClick={addGene}
                className="bg-slate-100 hover:bg-slate-200 text-slate-600 px-3 rounded-lg transition-colors"
              >
                <Plus size={20} />
              </button>
            </div>
            <div className="space-y-2 max-h-48 overflow-y-auto">
              {config.targetGenes.map(gene => (
                <div key={gene} className="flex items-center justify-between bg-slate-50 px-3 py-2 rounded-lg border border-slate-100">
                  <span className="text-sm font-medium text-slate-700">{gene}</span>
                  <button 
                    onClick={() => removeGene(gene)}
                    className="text-slate-400 hover:text-red-500 transition-colors"
                  >
                    <Trash2 size={16} />
                  </button>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      <div className="mt-8 flex justify-end">
        <button
          onClick={() => onNext(config)}
          className="bg-science-600 hover:bg-science-700 text-white px-8 py-3 rounded-lg font-medium shadow-lg shadow-science-500/20 transition-all hover:scale-105 active:scale-95"
        >
          下一步：录入数据
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { QpcrConfig, QpcrRawData } from '../../types';
import { FileSpreadsheet, AlertCircle, CheckCircle2, ChevronLeft, ChevronRight, Clipboard } from 'lucide-react';

interface Props {
  config: QpcrConfig;
  initialData: QpcrRawData;
  onNext: (data: QpcrRawData) => void;
  onBack: () => void;
}

export const QpcrDataInput: React.FC<Props> = ({ config, initialData, onNext, onBack }) => {
  const [data, setData] = useState<QpcrRawData>(initialData);
  const [activeGroupIndex, setActiveGroupIndex] = useState(0);

  const currentGroup = config.groups[activeGroupIndex];
  const allGenes = [config.referenceGene, ...config.targetGenes];

  // Initialize data structure if empty
  useEffect(() => {
    const newData = { ...data };
    let hasChanges = false;
    config.groups.forEach(group => {
      if (!newData[group]) {
        newData[group] = {};
        hasChanges = true;
      }
      allGenes.forEach(gene => {
        if (!newData[group][gene]) {
          newData[group][gene] = Array(config.replicates).fill(null);
          hasChanges = true;
        }
      });
    });
    if (hasChanges) setData(newData);
  }, [config, data, allGenes]);

  // Handle manual input change
  const handleInputChange = (gene: string, index: number, value: string) => {
    const numVal = value === '' ? null : parseFloat(value);
    const newData = { ...data };
    newData[currentGroup][gene] = [...newData[currentGroup][gene]];
    newData[currentGroup][gene][index] = isNaN(numVal as number) ? null : numVal;
    setData(newData);
  };

  // Handle paste for a specific gene column
  const handlePaste = (e: React.ClipboardEvent, gene: string) => {
    e.preventDefault();
    const pastedText = e.clipboardData.getData('text');
    // Split by newlines or spaces
    const values = pastedText.split(/[\n\s]+/).filter(v => v.trim() !== '').map(parseFloat);

    if (values.some(isNaN)) {
      alert('粘贴内容包含非数字字符，请检查。');
      return;
    }

    const newData = { ...data };
    const currentValues = [...newData[currentGroup][gene]];

    // Fill as many slots as possible up to replicates limit
    values.forEach((val, idx) => {
      if (idx < config.replicates) {
        currentValues[idx] = val;
      }
    });

    newData[currentGroup][gene] = currentValues;
    setData(newData);
  };

  const isGroupComplete = (group: string) => {
    if (!data[group]) return false;
    return allGenes.every(gene => {
      const vals = data[group][gene];
      return vals && vals.every(v => v !== null);
    });
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-8 max-w-6xl mx-auto min-h-[600px] flex flex-col">
      <div className="flex items-center justify-between mb-6 border-b border-slate-100 pb-4">
        <div className="flex items-center gap-3">
          <div className="bg-emerald-100 p-2 rounded-lg text-emerald-600">
            <FileSpreadsheet size={24} />
          </div>
          <div>
            <h2 className="text-xl font-bold text-slate-800">数据录入</h2>
            <p className="text-sm text-slate-500">
              当前分组: <span className="font-bold text-science-600">{currentGroup}</span> 
              {config.controlGroup === currentGroup && <span className="ml-2 text-xs bg-slate-100 px-2 py-0.5 rounded text-slate-500">对照组</span>}
            </p>
          </div>
        </div>

        <div className="flex items-center gap-2">
           <button 
            onClick={onBack}
            className="text-slate-500 hover:text-slate-800 px-4 py-2 text-sm font-medium"
          >
            返回设置
          </button>
          <div className="text-sm text-slate-400">
            步骤 2/3
          </div>
        </div>
      </div>

      {/* Tabs for Groups */}
      <div className="flex gap-2 mb-6 overflow-x-auto pb-2">
        {config.groups.map((group, idx) => (
          <button
            key={group}
            onClick={() => setActiveGroupIndex(idx)}
            className={`
              flex items-center gap-2 px-4 py-2 rounded-lg text-sm font-medium whitespace-nowrap transition-all
              ${activeGroupIndex === idx 
                ? 'bg-science-600 text-white shadow-md' 
                : 'bg-slate-50 text-slate-600 hover:bg-slate-100'}
            `}
          >
            {group}
            {isGroupComplete(group) ? <CheckCircle2 size={14} className="text-emerald-300" /> : <div className="w-3 h-3 rounded-full bg-slate-300 opacity-50"/>}
          </button>
        ))}
      </div>

      {/* Data Entry Grid */}
      <div className="flex-1 overflow-x-auto">
        <div className="bg-amber-50 border border-amber-100 rounded-lg p-4 mb-6 flex items-start gap-3">
            <AlertCircle size={20} className="text-amber-500 shrink-0 mt-0.5" />
            <p className="text-sm text-amber-700">
                <strong>提示：</strong> 您可以直接从 Excel 或 Word 复制一列数据，并在下方的输入框中按 <span className="font-mono bg-amber-100 px-1 rounded">Ctrl+V</span> 直接粘贴。
            </p>
        </div>

        <div className="grid gap-6" style={{ gridTemplateColumns: `repeat(${allGenes.length}, minmax(200px, 1fr))` }}>
          {allGenes.map((gene) => (
            <div key={gene} className={`rounded-xl border ${gene === config.referenceGene ? 'border-purple-200 bg-purple-50/30' : 'border-slate-200 bg-white'}`}>
              <div className={`p-3 border-b ${gene === config.referenceGene ? 'border-purple-100 bg-purple-100/50' : 'border-slate-100 bg-slate-50'} rounded-t-xl`}>
                <div className="flex items-center justify-between">
                    <span className="font-bold text-slate-700">{gene}</span>
                    {gene === config.referenceGene && <span className="text-[10px] uppercase tracking-wide bg-purple-200 text-purple-700 px-1.5 py-0.5 rounded">Ref</span>}
                </div>
              </div>
              <div className="p-3 space-y-2">
                {Array.from({ length: config.replicates }).map((_, idx) => (
                  <div key={idx} className="flex items-center gap-2">
