import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Upload, Plus, Trash2, Maximize, Check, BarChart3, AlertCircle, RotateCcw } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

// --- Types ---

interface Roi {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface WbSample {
  id: string;
  name: string;
  isControl: boolean;
  targetRoi?: Roi;
  refRoi?: Roi;
  // Computed values
  targetDensity?: number;
  refDensity?: number;
  normalizedRatio?: number; // Target / Ref
  relativeExpression?: number; // Ratio / Control_Ratio
}

// --- Helper Functions ---

const calculateIntegratedDensity = (
  ctx: CanvasRenderingContext2D,
  roi: Roi
): number => {
  if (roi.w <= 0 || roi.h <= 0) return 0;

  const imageData = ctx.getImageData(roi.x, roi.y, roi.w, roi.h);
  const data = imageData.data;
  let totalDensity = 0;

  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    // Simple luminance conversion
    const gray = 0.299 * r + 0.587 * g + 0.114 * b;
    // Invert because bands are dark on white background
    // If background is 255 (white), density is 0.
    // If band is 0 (black), density is 255.
    const density = 255 - gray;
    totalDensity += density;
  }

  return totalDensity;
};

// --- Main Component ---

export const WesternTool: React.FC = () => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [imageSrc, setImageSrc] = useState<string | null>(null);

  // Samples State
  const [samples, setSamples] = useState<WbSample[]>([
    { id: '1', name: 'Control', isControl: true },
    { id: '2', name: 'Sample 1', isControl: false },
    { id: '3', name: 'Sample 2', isControl: false },
  ]);

  // Annotation State
  const [activeAnnotation, setActiveAnnotation] = useState<{ sampleId: string; type: 'target' | 'ref' } | null>(null);

  // Canvas Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLImageElement | null>(null);

  // Dragging State for Drawing
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentRect, setCurrentRect] = useState<Roi | null>(null);

  // --- Step 1: Logic (Upload) ---

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImageSrc(event.target?.result as string);
        setStep(2);
      };
      reader.readAsDataURL(file);
    }
  };

  const addSample = () => {
    const newId = (samples.length + 1).toString();
    setSamples([...samples, { id: newId, name: `Sample ${samples.length}`, isControl: false }]);
  };

  const removeSample = (id: string) => {
    if (samples.length <= 1) return;
    setSamples(samples.filter(s => s.id !== id));
  };

  const updateSampleName = (id: string, name: string) => {
    setSamples(samples.map(s => s.id === id ? { ...s, name } : s));
  };

  const setControlSample = (id: string) => {
    setSamples(samples.map(s => ({ ...s, isControl: s.id === id })));
  };

  // --- Step 2: Logic (Annotation) ---

  // Initialize Canvas Image
  useEffect(() => {
    if (step === 2 && imageSrc && canvasRef.current && containerRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const img = new Image();
      img.src = imageSrc;
      img.onload = () => {
        imageRef.current = img;

        // Fit image to container width while maintaining aspect ratio
        const containerWidth = containerRef.current?.clientWidth || 800;
        const scale = containerWidth / img.width;

        canvas.width = img.width;
        canvas.height = img.height;

        // We display the canvas scaled via CSS style, but internal resolution keeps original image quality
        canvas.style.width = '100%';
        canvas.style.height = 'auto';

        ctx?.drawImage(img, 0, 0);
        drawOverlays();
      };
    }
  }, [step, imageSrc]);

  // Redraw when ROIs change
  useEffect(() => {
    drawOverlays();
  }, [samples, currentRect, activeAnnotation]);

  const drawOverlays = () => {
    const canvas = canvasRef.current;
    if (!canvas || !imageRef.current) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear and redraw image
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(imageRef.current, 0, 0);

    // Draw saved ROIs
    samples.forEach(sample => {
      if (sample.targetRoi) drawRoi(ctx, sample.targetRoi, '#3b82f6', 'T'); // Blue for Target
      if (sample.refRoi) drawRoi(ctx, sample.refRoi, '#10b981', 'R'); // Green for Ref
    });

    // Draw current dragging rect
    if (currentRect && activeAnnotation) {
       const color = activeAnnotation.type === 'target' ? '#3b82f6' : '#10b981';
       drawRoi(ctx, currentRect, color, '', true);
    }
  };

  const drawRoi = (ctx: CanvasRenderingContext2D, roi: Roi, color: string, label: string, isDashed = false) => {
    ctx.beginPath();
    ctx.lineWidth = 3;
    ctx.strokeStyle = color;
    if (isDashed) ctx.setLineDash([6, 3]);
    else ctx.setLineDash([]);
    ctx.rect(roi.x, roi.y, roi.w, roi.h);
    ctx.stroke();

    // Fill slightly
    ctx.fillStyle = color + '33'; // 20% opacity
    ctx.fill();

    if (label) {
        ctx.fillStyle = color;
        ctx.font = 'bold 24px Arial';
        ctx.fillText(label, roi.x, roi.y - 5);
    }
  };

  const getCanvasCoordinates = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!activeAnnotation) return;
    setIsDrawing(true);
    const pos = getCanvasCoordinates(e);
    setStartPos(pos);
    setCurrentRect({ x: pos.x, y: pos.y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing || !activeAnnotation) return;
    const pos = getCanvasCoordinates(e);
    setCurrentRect({
      x: Math.min(startPos.x, pos.x),
      y: Math.min(startPos.y, pos.y),
      w: Math.abs(pos.x - startPos.x),
      h: Math.abs(pos.y - startPos.y)
    });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !activeAnnotation || !currentRect) return;
    setIsDrawing(false);

    // Save ROI to the active sample
    const updatedSamples = samples.map(s => {
      if (s.id === activeAnnotation.sampleId) {
        return {
          ...s,
          [activeAnnotation.type === 'target' ? 'targetRoi' : 'refRoi']: currentRect
        };
      }
      return s;
    });

    setSamples(updatedSamples);
    setCurrentRect(null);
    setActiveAnnotation(null); // Deselect after drawing
  };

  // --- Step 3: Analysis ---

  const performAnalysis = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 1. Calculate Raw Densities
    const rawResults = samples.map(s => ({
        ...s,
        targetDensity: s.targetRoi ? calculateIntegratedDensity(ctx, s.targetRoi) : 0,
        refDensity: s.refRoi ? calculateIntegratedDensity(ctx, s.refRoi) : 0,
    }));

    // 2. Normalize by Internal Reference (Target / Ref)
    const normalizedResults = rawResults.map(s => ({
        ...s,
        normalizedRatio: (s.targetDensity && s.refDensity) ? (s.targetDensity / s.refDensity) : 0
    }));

    // 3. Normalize to Control Group (Ratio / Control_Ratio)
    const controlSample = normalizedResults.find(s => s.isControl);
    const controlRatio = controlSample?.normalizedRatio || 1; // Avoid divide by zero

    const finalResults = normalizedResults.map(s => ({
        ...s,
        relativeExpression: s.normalizedRatio / (controlRatio || 1) // If control is 0, just use 1
    }));

    setSamples(finalResults);
    setStep(3);
  };

  // --- Render Helpers ---

  const chartData = useMemo(() => {
    return samples.map(s => ({
      name: s.name,
      expression: parseFloat((s.relativeExpression || 0).toFixed(2)),
      rawT: Math.round(s.targetDensity || 0),
      rawR: Math.round(s.refDensity || 0),
    }));
  }, [samples]);

  // --- View ---

  return (
    <div className="w-full animate-fade-in max-w-7xl mx-auto">

      {/* Header */}
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Activity className="text-emerald-500" />
            Western Blot 灰度分析
        </h2>
        <p className="text-slate-500 mt-1">图像半定量分析工具</p>
      </div>

      {step === 1 && (
        <div className="bg-white rounded-2xl p-12 border-2 border-dashed border-slate-300 text-center hover:border-emerald-400 transition-colors">
            <div className="bg-emerald-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                <Upload size={40} className="text-emerald-500" />
            </div>
            <h3 className="text-xl font-medium text-slate-800 mb-2">上传 Western Blot 条带图像</h3>
            <p className="text-slate-500 mb-6 max-w-md mx-auto">支持 JPG, PNG 格式。请确保图像清晰，包含目的蛋白和内参蛋白。</p>
            <input 
                type="file" 
                accept="image/*" 
                onChange={handleImageUpload} 
                id="wb-upload" 
                className="hidden"
            />
            <label 
                htmlFor="wb-upload"
                className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-lg font-medium cursor-pointer transition-all shadow-lg shadow-emerald-500/20"
            >
                选择图片文件
            </label>
        </div>
      )}

      {step === 2 && (
        <div className="grid lg:grid-cols-3 gap-8 items-start">
            {/* Left: Canvas */}
            <div className="lg:col-span-2 bg-slate-900 rounded-xl overflow-hidden shadow-lg relative" ref={containerRef}>
                <div className="absolute top-4 left-4 z-10 bg-black/60 backdrop-blur text-white text-xs px-3 py-1 rounded-full pointer-events-none">
                    {activeAnnotation 
                        ? `请在图中框选: ${samples.find(s => s.id === activeAnnotation.sampleId)?.name} - ${activeAnnotation.type === 'target' ? '目的蛋白' : '内参蛋白'}` 
                        : '请在右侧列表中点击按钮开始框选'}
                </div>
                <canvas 
                    ref={canvasRef}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                    className={`block w-full cursor-crosshair touch-none ${activeAnnotation ? 'cursor-crosshair' : 'cursor-default'}`}
                />
            </div>

            {/* Right: Controls */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 space-y-6 max-h-[calc(100vh-200px)] overflow-y-auto">
                <div>
                    <h3 className="font-bold text-slate-800 mb-4 flex items-center justify-between">
                        样本列表
                        <button onClick={addSample} className="text-emerald-600 hover:bg-emerald-50 p-1 rounded transition-colors">
                            <Plus size={20} />
                        </button>
                    </h3>

                    <div className="space-y-4">
                        {samples.map((sample) => (
                            <div key={sample.id} className="bg-slate-50 rounded-lg p-3 border border-slate-100 transition-all hover:border-emerald-200">
                                <div className="flex items-center gap-2 mb-3">
                                    <input 
                                        type="radio" 
                                        name="controlGroup" 
                                        checked={sample.isControl} 
                                        onChange={() => setControlSample(sample.id)}
                                        className="text-emerald-500 focus:ring-emerald-500"
                                        title="设为对照组 (Control)"
                                    />
                                    <input 
                                        type="text" 
                                        value={sample.name} 
                                        onChange={(e) => updateSampleName(sample.id, e.target.value)}
                                        className="bg-transparent border-b border-transparent hover:border-slate-300 focus:border-emerald-500 outline-none text-sm font-medium text-slate-700 w-full"
                                    />
                                    <button onClick={() => removeSample(sample.id)} className="text-slate-400 hover:text-red-500">
                                        <Trash2 size={14} />
                                    </button>
                                </div>

                                <div className="grid grid-cols-2 gap-2">
                                    <button 
                                        onClick={() => setActiveAnnotation({ sampleId: sample.id, type: 'target' })}
                                        className={`
                                            px-2 py-2 rounded text-xs font-medium flex items-center justify-center gap-1 border transition-all
                                            ${sample.targetRoi ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-200 text-slate-500 hover:border-blue-300'}
                                            ${activeAnnotation?.sampleId === sample.id && activeAnnotation.type === 'target' ? 'ring-2 ring-blue-500 ring-offset-1' : ''}
                                        `}
                                    >
                                        {sample.targetRoi ? <Check size={12} /> : <Maximize size={12} />}
                                        目的蛋白
                                    </button>
                                    <button 
                                         onClick={() => setActiveAnnotation({ sampleId: sample.id, type: 'ref' })}
                                         className={`
                                            px-2 py-2 rounded text-xs font-medium flex items-center justify-center gap-1 border transition-all
                                            ${sample.refRoi ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-300'}
                                            ${activeAnnotation?.sampleId === sample.id && activeAnnotation.type === 'ref' ? 'ring-2 ring-emerald-500 ring-offset-1' : ''}
                                        `}
                                    >
                                        {sample.refRoi ? <Check size={12} /> : <Maximize size={12} />}
                                        内参蛋白
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="pt-4 border-t border-slate-100">
                    <button 
                        onClick={performAnalysis}
                        disabled={samples.some(s => !s.targetRoi || !s.refRoi)}
                        className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 disabled:cursor-not-allowed text-white py-3 rounded-lg font-bold shadow-lg shadow-emerald-500/20 transition-all active:scale-95 flex items-center justify-center gap-2"
                    >
                        <BarChart3 size={20} />
                        开始分析
                    </button>
                    {samples.some(s => !s.targetRoi || !s.refRoi) && (
                        <p className="text-xs text-center text-slate-400 mt-2">请标记所有样本的条带区域</p>
                    )}
                </div>
            </div>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-8">
            <div className="flex items-center justify-between bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                 <h3 className="text-lg font-bold text-slate-800">分析结果</h3>
                 <div className="flex gap-2">
                     <button 
                        onClick={() => setStep(2)} 
                        className="px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-lg text-sm font-medium transition-colors"
                     >
                        调整选区
                     </button>
                     <button 
                        onClick={() => { setStep(1); setSamples([{ id: '1', name: 'Control', isControl: true }]); setImageSrc(null); }} 
                        className="px-4 py-2 bg-slate-800 hover:bg-slate-900 text-white rounded-lg text-sm font-medium flex items-center gap-2"
                     >
                        <RotateCcw size={16} /> 重新开始
                     </button>
                 </div>
            </div>

            <div className="grid md:grid-cols-2 gap-8">
                {/* Chart */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                    <h4 className="font-bold text-slate-700 mb-6 pl-2 border-l-4 border-emerald-500">相对表达量 (Normalized to Control)</h4>
                    <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                             <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#64748b' }} dy={10} />
                                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748b' }} />
                                <Tooltip cursor={{ fill: '#f1f5f9' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                                <Bar dataKey="expression" fill="#10b981" radius={[6, 6, 0, 0]} name="Relative Expression" />
                             </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Table */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 overflow-hidden">
                    <h4 className="font-bold text-slate-700 mb-6 pl-2 border-l-4 border-blue-500">详细数据</h4>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-slate-50 text-slate-500 font-medium">
                                <tr>
                                    <th className="px-3 py-2 rounded-l-lg">样本</th>
                                    <th className="px-3 py-2 text-right">Raw (Target)</th>
                                    <th className="px-3 py-2 text-right">Raw (Ref)</th>
                                    <th className="px-3 py-2 text-right">Ratio (T/R)</th>
                                    <th className="px-3 py-2 text-right rounded-r-lg">Rel. Exp.</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {samples.map(s => (
                                    <tr key={s.id} className="hover:bg-slate-50">
                                        <td className="px-3 py-3 font-medium text-slate-700">
                                            {s.name} {s.isControl && <span className="text-xs bg-slate-100 text-slate-400 px-1.5 rounded ml-1">Ctrl</span>}
                                        </td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono">{Math.round(s.targetDensity || 0).toLocaleString()}</td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono">{Math.round(s.refDensity || 0).toLocaleString()}</td>
                                        <td className="px-3 py-3 text-right text-blue-600 font-mono">{(s.normalizedRatio || 0).toFixed(3)}</td>
                                        <td className="px-3 py-3 text-right font-bold text-emerald-600 font-mono">{(s.relativeExpression || 0).toFixed(2)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            <div className="bg-amber-50 border border-amber-100 rounded-xl p-4 flex items-start gap-3 text-sm text-amber-800">
                <AlertCircle className="shrink-0 mt-0.5 text-amber-500" size={18} />
                <p>
                    <strong>注意：</strong> 本工具使用简单的 "Integrated Density (Sum of Inverted Gray Value)" 算法。
                    为保证结果准确，建议上传背景干净的图片。如果背景噪音较大，结果可能会受到影响。
                    灰度计算公式: Density = Σ (255 - (0.299R + 0.587G + 0.114B))。
                </p>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Upload, Plus, Trash2, Maximize, Check, BarChart3, AlertCircle, RotateCcw, Activity } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';

// --- Types ---

interface Roi {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface WbSample {
  id: string;
  name: string;
  isControl: boolean;
  targetRoi?: Roi;
  refRoi?: Roi;
  // Computed values
  targetDensity?: number;
  refDensity?: number;
  normalizedRatio?: number; // Target / Ref
  relativeExpression?: number; // Ratio / Control_Ratio
}

// --- Helper Functions ---

const calculateIntegratedDensity = (
  ctx: CanvasRenderingContext2D,
  roi: Roi
): number => {
  if (roi.w <= 0 || roi.h <= 0) return 0;

  const imageData = ctx.getImageData(roi.x, roi.y, roi.w, roi.h);
  const data = imageData.data;
  let totalDensity = 0;

  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    // Simple luminance conversion
    const gray = 0.299 * r + 0.587 * g + 0.114 * b;
    // Invert because bands are dark on white background
    // If background is 255 (white), density is 0.
    // If band is 0 (black), density is 255.
    const density = 255 - gray;
    totalDensity += density;
  }

  return totalDensity;
};

// --- Main Component ---

export const WesternTool: React.FC = () => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [imageSrc, setImageSrc] = useState<string | null>(null);

  // Samples State
  const [samples, setSamples] = useState<WbSample[]>([
    { id: '1', name: 'Control', isControl: true },
    { id: '2', name: 'Sample 1', isControl: false },
    { id: '3', name: 'Sample 2', isControl: false },
  ]);

  // Annotation State
  const [activeAnnotation, setActiveAnnotation] = useState<{ sampleId: string; type: 'target' | 'ref' } | null>(null);

  // Canvas Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLImageElement | null>(null);

  // Dragging State for Drawing
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentRect, setCurrentRect] = useState<Roi | null>(null);

  // --- Step 1: Logic (Upload) ---

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setImageSrc(event.target?.result as string);
        setStep(2);
      };
      reader.readAsDataURL(file);
    }
  };

  const addSample = () => {
    const newId = (samples.length + 1).toString();
    setSamples([...samples, { id: newId, name: `Sample ${samples.length}`, isControl: false }]);
  };

  const removeSample = (id: string) => {
    if (samples.length <= 1) return;
    setSamples(samples.filter(s => s.id !== id));
  };

  const updateSampleName = (id: string, name: string) => {
    setSamples(samples.map(s => s.id === id ? { ...s, name } : s));
  };

  const setControlSample = (id: string) => {
    setSamples(samples.map(s => ({ ...s, isControl: s.id === id })));
  };

  // --- Step 2: Logic (Annotation) ---

  // Initialize Canvas Image
  useEffect(() => {
    if (step === 2 && imageSrc && canvasRef.current && containerRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const img = new Image();
      img.src = imageSrc;
      img.onload = () => {
        imageRef.current = img;

        // Fit image to container width while maintaining aspect ratio
        const containerWidth = containerRef.current?.clientWidth || 800;
        const scale = containerWidth / img.width;

        canvas.width = img.width;
        canvas.height = img.height;

        // We display the canvas scaled via CSS style, but internal resolution keeps original image quality
        canvas.style.width = '100%';
        canvas.style.height = 'auto';

        ctx?.drawImage(img, 0, 0);
        drawOverlays();
      };
    }
  }, [step, imageSrc]);

  // Redraw when ROIs change
  useEffect(() => {
    drawOverlays();
  }, [samples, currentRect, activeAnnotation]);

  const drawOverlays = () => {
    const canvas = canvasRef.current;
    if (!canvas || !imageRef.current) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear and redraw image
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(imageRef.current, 0, 0);

    // Draw saved ROIs
    samples.forEach(sample => {
      if (sample.targetRoi) drawRoi(ctx, sample.targetRoi, '#3b82f6', 'T'); // Blue for Target
      if (sample.refRoi) drawRoi(ctx, sample.refRoi, '#10b981', 'R'); // Green for Ref
    });

    // Draw current dragging rect
    if (currentRect && activeAnnotation) {
       const color = activeAnnotation.type === 'target' ? '#3b82f6' : '#10b981';
       drawRoi(ctx, currentRect, color, '', true);
    }
  };

  const drawRoi = (ctx: CanvasRenderingContext2D, roi: Roi, color: string, label: string, isDashed = false) => {
    ctx.beginPath();
    ctx.lineWidth = 3;
    ctx.strokeStyle = color;
    if (isDashed) ctx.setLineDash([6, 3]);
    else ctx.setLineDash([]);
    ctx.rect(roi.x, roi.y, roi.w, roi.h);
    ctx.stroke();

    // Fill slightly
    ctx.fillStyle = color + '33'; // 20% opacity
    ctx.fill();

    if (label) {
        ctx.fillStyle = color;
        ctx.font = 'bold 24px Arial';
        ctx.fillText(label, roi.x, roi.y - 5);
    }
  };

  const getCanvasCoordinates = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!activeAnnotation) return;
    setIsDrawing(true);
    const pos = getCanvasCoordinates(e);
    setStartPos(pos);
    setCurrentRect({ x: pos.x, y: pos.y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing || !activeAnnotation) return;
    const pos = getCanvasCoordinates(e);
    setCurrentRect({
      x: Math.min(startPos.x, pos.x),
      y: Math.min(startPos.y, pos.y),
      w: Math.abs(pos.x - startPos.x),
      h: Math.abs(pos.y - startPos.y)
    });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !activeAnnotation || !currentRect) return;
    setIsDrawing(false);

    // Save ROI to the active sample
    const updatedSamples = samples.map(s => {
      if (s.id === activeAnnotation.sampleId) {
        return {
          ...s,
          [activeAnnotation.type === 'target' ? 'targetRoi' : 'refRoi']: currentRect
        };
      }
      return s;
    });

    setSamples(updatedSamples);
    setCurrentRect(null);
    setActiveAnnotation(null); // Deselect after drawing
  };

  // --- Step 3: Analysis ---

  const performAnalysis = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 1. Calculate Raw Densities
    const rawResults = samples.map(s => ({
        ...s,
        targetDensity: s.targetRoi ? calculateIntegratedDensity(ctx, s.targetRoi) : 0,
        refDensity: s.refRoi ? calculateIntegratedDensity(ctx, s.refRoi) : 0,
    }));

    // 2. Normalize by Internal Reference (Target / Ref)
    const normalizedResults = rawResults.map(s => ({
        ...s,
        normalizedRatio: (s.targetDensity && s.refDensity) ? (s.targetDensity / s.refDensity) : 0
    }));

    // 3. Normalize to Control Group (Ratio / Control_Ratio)
    const controlSample = normalizedResults.find(s => s.isControl);
    const controlRatio = controlSample?.normalizedRatio || 1; // Avoid divide by zero

    const finalResults = normalizedResults.map(s => ({
        ...s,
        relativeExpression: s.normalizedRatio / (controlRatio || 1) // If control is 0, just use 1
    }));

    setSamples(finalResults);
    setStep(3);
  };

  // --- Render Helpers ---

  const chartData = useMemo(() => {
    return samples.map(s => ({
      name: s.name,
      expression: parseFloat((s.relativeExpression || 0).toFixed(2)),
      rawT: Math.round(s.targetDensity || 0),
      rawR: Math.round(s.refDensity || 0),
    }));
  }, [samples]);

  // --- View ---

  return (
    <div className="w-full animate-fade-in max-w-7xl mx-auto">

      {/* Header */}
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Activity className="text-emerald-500" />
            Western Blot 灰度分析
        </h2>
        <p className="text-slate-500 mt-1">图像半定量分析工具</p>
      </div>

      {step === 1 && (
        <div className="bg-white rounded-2xl p-12 border-2 border-dashed border-slate-300 text-center hover:border-emerald-400 transition-colors">
            <div className="bg-emerald-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                <Upload size={40} className="text-emerald-500" />
            </div>
            <h3 className="text-xl font-medium text-slate-800 mb-2">上传 Western Blot 条带图像</h3>
            <p className="text-slate-500 mb-6 max-w-md mx-auto">支持 JPG, PNG 格式。请确保图像清晰，包含目的蛋白和内参蛋白。</p>
            <input 
                type="file" 
                accept="image/*" 
                onChange={handleImageUpload} 
                id="wb-upload" 
                className="hidden"
            />
            <label 
                htmlFor="wb-upload"
                className="bg-emerald-600 hover:bg-emerald-700 text-white px-8 py-3 rounded-lg font-medium cursor-pointer transition-all shadow-lg shadow-emerald-500/20"
            >
                选择图片文件
            </label>
        </div>
      )}

      {step === 2 && (
        <div className="grid lg:grid-cols-3 gap-8 items-start">
            {/* Left: Canvas */}
            <div className="lg:col-span-2 bg-slate-900 rounded-xl overflow-hidden shadow-lg relative" ref={containerRef}>
                <div className="absolute top-4 left-4 z-10 bg-black/60 backdrop-blur text-white text-xs px-3 py-1 rounded-full pointer-events-none">
                    {activeAnnotation 
                        ? `请在图中框选: ${samples.find(s => s.id === activeAnnotation.sampleId)?.name} - ${activeAnnotation.type === 'target' ? '目的蛋白' : '内参蛋白'}` 
                        : '请在右侧列表中点击按钮开始框选'}
                </div>
                <canvas 
                    ref={canvasRef}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                    className={`block w-full cursor-crosshair touch-none ${activeAnnotation ? 'cursor-crosshair' : 'cursor-default'}`}
                />
            </div>

            {/* Right: Controls */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 space-y-6 max-h-[calc(100vh-200px)] overflow-y-auto">
                <div>
                    <h3 className="font-bold text-slate-800 mb-4 flex items-center justify-between">
                        样本列表
                        <button onClick={addSample} className="text-emerald-600 hover:bg-emerald-50 p-1 rounded transition-colors">
                            <Plus size={20} />
                        </button>
                    </h3>

                    <div className="space-y-4">
                        {samples.map((sample) => (
                            <div key={sample.id} className="bg-slate-50 rounded-lg p-3 border border-slate-100 transition-all hover:border-emerald-200">
                                <div className="flex items-center gap-2 mb-3">
                                    <input 
                                        type="radio" 
                                        name="controlGroup" 
                                        checked={sample.isControl} 
                                        onChange={() => setControlSample(sample.id)}
                                        className="text-emerald-500 focus:ring-emerald-500"
                                        title="设为对照组 (Control)"
                                    />
                                    <input 
                                        type="text" 
                                        value={sample.name} 
                                        onChange={(e) => updateSampleName(sample.id, e.target.value)}
                                        className="bg-transparent border-b border-transparent hover:border-slate-300 focus:border-emerald-500 outline-none text-sm font-medium text-slate-700 w-full"
                                    />
                                    <button onClick={() => removeSample(sample.id)} className="text-slate-400 hover:text-red-500">
                                        <Trash2 size={14} />
                                    </button>
                                </div>

                                <div className="grid grid-cols-2 gap-2">
                                    <button 
                                        onClick={() => setActiveAnnotation({ sampleId: sample.id, type: 'target' })}
                                        className={`
                                            px-2 py-2 rounded text-xs font-medium flex items-center justify-center gap-1 border transition-all
                                            ${sample.targetRoi ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-200 text-slate-500 hover:border-blue-300'}
                                            ${activeAnnotation?.sampleId === sample.id && activeAnnotation.type === 'target' ? 'ring-2 ring-blue-500 ring-offset-1' : ''}
                                        `}
                                    >
                                        {sample.targetRoi ? <Check size={12} /> : <Maximize size={12} />}
                                        目的蛋白
                                    </button>
                                    <button 
                                         onClick={() => setActiveAnnotation({ sampleId: sample.id, type: 'ref' })}
                                         className={`
                                            px-2 py-2 rounded text-xs font-medium flex items-center justify-center gap-1 border transition-all
                                            ${sample.refRoi ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-300'}
                                            ${activeAnnotation?.sampleId === sample.id && activeAnnotation.type === 'ref' ? 'ring-2 ring-emerald-500 ring-offset-1' : ''}
                                        `}
                                    >
                                        {sample.refRoi ? <Check size={12} /> : <Maximize size={12} />}
                                        内参蛋白
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="pt-4 border-t border-slate-100">
                    <button 
                        onClick={performAnalysis}
                        disabled={samples.some(s => !s.targetRoi || !s.refRoi)}
                        className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 disabled:cursor-not-allowed text-white py-3 rounded-lg font-bold shadow-lg shadow-emerald-500/20 transition-all active:scale-95 flex items-center justify-center gap-2"
                    >
                        <BarChart3 size={20} />
                        开始分析
                    </button>
                    {samples.some(s => !s.targetRoi || !s.refRoi) && (
                        <p className="text-xs text-center text-slate-400 mt-2">请标记所有样本的条带区域</p>
                    )}
                </div>
            </div>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-8">
            <div className="flex items-center justify-between bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                 <h3 className="text-lg font-bold text-slate-800">分析结果</h3>
                 <div className="flex gap-2">
                     <button 
                        onClick={() => setStep(2)} 
                        className="px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-lg text-sm font-medium transition-colors"
                     >
                        调整选区
                     </button>
                     <button 
                        onClick={() => { setStep(1); setSamples([{ id: '1', name: 'Control', isControl: true }]); setImageSrc(null); }} 
                        className="px-4 py-2 bg-slate-800 hover:bg-slate-900 text-white rounded-lg text-sm font-medium flex items-center gap-2"
                     >
                        <RotateCcw size={16} /> 重新开始
                     </button>
                 </div>
            </div>

            <div className="grid md:grid-cols-2 gap-8">
                {/* Chart */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                    <h4 className="font-bold text-slate-700 mb-6 pl-2 border-l-4 border-emerald-500">相对表达量 (Normalized to Control)</h4>
                    <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                             <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#64748b' }} dy={10} />
                                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748b' }} />
                                <Tooltip cursor={{ fill: '#f1f5f9' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                                <Bar dataKey="expression" fill="#10b981" radius={[6, 6, 0, 0]} name="Relative Expression" />
                             </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Table */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 overflow-hidden">
                    <h4 className="font-bold text-slate-700 mb-6 pl-2 border-l-4 border-blue-500">详细数据</h4>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-slate-50 text-slate-500 font-medium">
                                <tr>
                                    <th className="px-3 py-2 rounded-l-lg">样本</th>
                                    <th className="px-3 py-2 text-right">Raw (Target)</th>
                                    <th className="px-3 py-2 text-right">Raw (Ref)</th>
                                    <th className="px-3 py-2 text-right">Ratio (T/R)</th>
                                    <th className="px-3 py-2 text-right rounded-r-lg">Rel. Exp.</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {samples.map(s => (
                                    <tr key={s.id} className="hover:bg-slate-50">
                                        <td className="px-3 py-3 font-medium text-slate-700">
                                            {s.name} {s.isControl && <span className="text-xs bg-slate-100 text-slate-400 px-1.5 rounded ml-1">Ctrl</span>}
                                        </td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono">{Math.round(s.targetDensity || 0).toLocaleString()}</td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono">{Math.round(s.refDensity || 0).toLocaleString()}</td>
                                        <td className="px-3 py-3 text-right text-blue-600 font-mono">{(s.normalizedRatio || 0).toFixed(3)}</td>
                                        <td className="px-3 py-3 text-right font-bold text-emerald-600 font-mono">{(s.relativeExpression || 0).toFixed(2)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            <div className="bg-amber-50 border border-amber-100 rounded-xl p-4 flex items-start gap-3 text-sm text-amber-800">
                <AlertCircle className="shrink-0 mt-0.5 text-amber-500" size={18} />
                <p>
                    <strong>注意：</strong> 本工具使用简单的 "Integrated Density (Sum of Inverted Gray Value)" 算法。
                    为保证结果准确，建议上传背景干净的图片。如果背景噪音较大，结果可能会受到影响。
                    灰度计算公式: Density = Σ (255 - (0.299R + 0.587G + 0.114B))。
                </p>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Upload, Plus, Trash2, Maximize, Check, BarChart3, AlertCircle, RotateCcw, Activity } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
// @ts-ignore
import UTIF from 'utif';

// --- Types ---

interface Roi {
  x: number;
  y: number;
  w: number;
  h: number;
}

interface WbSample {
  id: string;
  name: string;
  isControl: boolean;
  targetRoi?: Roi;
  refRoi?: Roi;
  // Computed values
  targetDensity?: number;
  refDensity?: number;
  normalizedRatio?: number; // Target / Ref
  relativeExpression?: number; // Ratio / Control_Ratio
}

// --- Helper Functions ---

const calculateIntegratedDensity = (
  ctx: CanvasRenderingContext2D,
  roi: Roi
): number => {
  if (roi.w <= 0 || roi.h <= 0) return 0;

  const imageData = ctx.getImageData(roi.x, roi.y, roi.w, roi.h);
  const data = imageData.data;
  let totalDensity = 0;

  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    // Simple luminance conversion
    const gray = 0.299 * r + 0.587 * g + 0.114 * b;
    // Invert because bands are dark on white background
    // If background is 255 (white), density is 0.
    // If band is 0 (black), density is 255.
    const density = 255 - gray;
    totalDensity += density;
  }

  return totalDensity;
};

// --- Main Component ---

export const WesternTool: React.FC = () => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [imageSrc, setImageSrc] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Samples State
  const [samples, setSamples] = useState<WbSample[]>([
    { id: '1', name: 'Control', isControl: true },
    { id: '2', name: 'Sample 1', isControl: false },
    { id: '3', name: 'Sample 2', isControl: false },
  ]);

  // Annotation State
  const [activeAnnotation, setActiveAnnotation] = useState<{ sampleId: string; type: 'target' | 'ref' } | null>(null);

  // Canvas Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const imageRef = useRef<HTMLImageElement | null>(null);

  // Dragging State for Drawing
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentRect, setCurrentRect] = useState<Roi | null>(null);

  // --- Step 1: Logic (Upload) ---

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsProcessing(true);

    // Check for TIFF
    const isTiff = file.type === 'image/tiff' || file.name.toLowerCase().endsWith('.tif') || file.name.toLowerCase().endsWith('.tiff');

    if (isTiff) {
        try {
            const buffer = await file.arrayBuffer();
            const ifds = UTIF.decode(buffer);
            if (ifds && ifds.length > 0) {
                const page = ifds[0];
                UTIF.decodeImage(buffer, page);
                const rgba = UTIF.toRGBA8(page);

                const canvas = document.createElement('canvas');
                canvas.width = page.width;
                canvas.height = page.height;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    const imageData = new ImageData(new Uint8ClampedArray(rgba.buffer), page.width, page.height);
                    ctx.putImageData(imageData, 0, 0);
                    setImageSrc(canvas.toDataURL('image/png'));
                    setStep(2);
                }
            } else {
                alert("无法解析 TIFF 文件，请尝试转换为 JPG 或 PNG。");
            }
        } catch (err) {
            console.error(err);
            alert("TIFF 文件处理失败，请确保文件未损坏或尝试转换为其他格式。");
        }
    } else {
        // Normal image (JPG, PNG)
        const reader = new FileReader();
        reader.onload = (event) => {
            setImageSrc(event.target?.result as string);
            setStep(2);
        };
        reader.readAsDataURL(file);
    }
    setIsProcessing(false);
  };

  const addSample = () => {
    const newId = (samples.length + 1).toString();
    setSamples([...samples, { id: newId, name: `Sample ${samples.length}`, isControl: false }]);
  };

  const removeSample = (id: string) => {
    if (samples.length <= 1) return;
    setSamples(samples.filter(s => s.id !== id));
  };

  const updateSampleName = (id: string, name: string) => {
    setSamples(samples.map(s => s.id === id ? { ...s, name } : s));
  };

  const setControlSample = (id: string) => {
    setSamples(samples.map(s => ({ ...s, isControl: s.id === id })));
  };

  // --- Step 2: Logic (Annotation) ---

  // Initialize Canvas Image
  useEffect(() => {
    if (step === 2 && imageSrc && canvasRef.current && containerRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const img = new Image();
      img.src = imageSrc;
      img.onload = () => {
        imageRef.current = img;

        // Fit image to container width while maintaining aspect ratio
        const containerWidth = containerRef.current?.clientWidth || 800;
        const scale = containerWidth / img.width;

        canvas.width = img.width;
        canvas.height = img.height;

        // We display the canvas scaled via CSS style, but internal resolution keeps original image quality
        canvas.style.width = '100%';
        canvas.style.height = 'auto';

        ctx?.drawImage(img, 0, 0);
        drawOverlays();
      };

      // Error handling for image loading
      img.onerror = () => {
          alert("图片加载失败，请检查文件格式。");
          setStep(1);
          setImageSrc(null);
      }
    }
  }, [step, imageSrc]);

  // Redraw when ROIs change
  useEffect(() => {
    drawOverlays();
  }, [samples, currentRect, activeAnnotation]);

  const drawOverlays = () => {
    const canvas = canvasRef.current;
    if (!canvas || !imageRef.current) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // Clear and redraw image
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.drawImage(imageRef.current, 0, 0);

    // Draw saved ROIs
    samples.forEach(sample => {
      if (sample.targetRoi) drawRoi(ctx, sample.targetRoi, '#3b82f6', 'T'); // Blue for Target
      if (sample.refRoi) drawRoi(ctx, sample.refRoi, '#10b981', 'R'); // Green for Ref
    });

    // Draw current dragging rect
    if (currentRect && activeAnnotation) {
       const color = activeAnnotation.type === 'target' ? '#3b82f6' : '#10b981';
       drawRoi(ctx, currentRect, color, '', true);
    }
  };

  const drawRoi = (ctx: CanvasRenderingContext2D, roi: Roi, color: string, label: string, isDashed = false) => {
    ctx.beginPath();
    ctx.lineWidth = 3;
    ctx.strokeStyle = color;
    if (isDashed) ctx.setLineDash([6, 3]);
    else ctx.setLineDash([]);
    ctx.rect(roi.x, roi.y, roi.w, roi.h);
    ctx.stroke();

    // Fill slightly
    ctx.fillStyle = color + '33'; // 20% opacity
    ctx.fill();

    if (label) {
        ctx.fillStyle = color;
        ctx.font = 'bold 24px Arial';
        ctx.fillText(label, roi.x, roi.y - 5);
    }
  };

  const getCanvasCoordinates = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!activeAnnotation) return;
    setIsDrawing(true);
    const pos = getCanvasCoordinates(e);
    setStartPos(pos);
    setCurrentRect({ x: pos.x, y: pos.y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing || !activeAnnotation) return;
    const pos = getCanvasCoordinates(e);
    setCurrentRect({
      x: Math.min(startPos.x, pos.x),
      y: Math.min(startPos.y, pos.y),
      w: Math.abs(pos.x - startPos.x),
      h: Math.abs(pos.y - startPos.y)
    });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !activeAnnotation || !currentRect) return;
    setIsDrawing(false);

    // Save ROI to the active sample
    const updatedSamples = samples.map(s => {
      if (s.id === activeAnnotation.sampleId) {
        return {
          ...s,
          [activeAnnotation.type === 'target' ? 'targetRoi' : 'refRoi']: currentRect
        };
      }
      return s;
    });

    setSamples(updatedSamples);
    setCurrentRect(null);
    setActiveAnnotation(null); // Deselect after drawing
  };

  // --- Step 3: Analysis ---

  const performAnalysis = () => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    // 1. Calculate Raw Densities
    const rawResults = samples.map(s => ({
        ...s,
        targetDensity: s.targetRoi ? calculateIntegratedDensity(ctx, s.targetRoi) : 0,
        refDensity: s.refRoi ? calculateIntegratedDensity(ctx, s.refRoi) : 0,
    }));

    // 2. Normalize by Internal Reference (Target / Ref)
    const normalizedResults = rawResults.map(s => ({
        ...s,
        normalizedRatio: (s.targetDensity && s.refDensity) ? (s.targetDensity / s.refDensity) : 0
    }));

    // 3. Normalize to Control Group (Ratio / Control_Ratio)
    const controlSample = normalizedResults.find(s => s.isControl);
    const controlRatio = controlSample?.normalizedRatio || 1; // Avoid divide by zero

    const finalResults = normalizedResults.map(s => ({
        ...s,
        relativeExpression: s.normalizedRatio / (controlRatio || 1) // If control is 0, just use 1
    }));

    setSamples(finalResults);
    setStep(3);
  };

  // --- Render Helpers ---

  const chartData = useMemo(() => {
    return samples.map(s => ({
      name: s.name,
      expression: parseFloat((s.relativeExpression || 0).toFixed(2)),
      rawT: Math.round(s.targetDensity || 0),
      rawR: Math.round(s.refDensity || 0),
    }));
  }, [samples]);

  // --- View ---

  return (
    <div className="w-full animate-fade-in max-w-7xl mx-auto">

      {/* Header */}
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Activity className="text-emerald-500" />
            Western Blot 灰度分析
        </h2>
        <p className="text-slate-500 mt-1">图像半定量分析工具</p>
      </div>

      {step === 1 && (
        <div className="bg-white rounded-2xl p-12 border-2 border-dashed border-slate-300 text-center hover:border-emerald-400 transition-colors">
            <div className="bg-emerald-50 w-20 h-20 rounded-full flex items-center justify-center mx-auto mb-6">
                <Upload size={40} className="text-emerald-500" />
            </div>
            <h3 className="text-xl font-medium text-slate-800 mb-2">上传 Western Blot 条带图像</h3>
            <p className="text-slate-500 mb-6 max-w-md mx-auto">支持 JPG, PNG, TIFF 格式。请确保图像清晰，包含目的蛋白和内参蛋白。</p>
            <input 
                type="file" 
                accept="image/png, image/jpeg, image/jpg, image/tiff, .tif, .tiff" 
                onChange={handleImageUpload} 
                id="wb-upload" 
                className="hidden"
            />
            <label 
                htmlFor="wb-upload"
                className={`
                    px-8 py-3 rounded-lg font-medium cursor-pointer transition-all shadow-lg shadow-emerald-500/20 inline-flex items-center gap-2
                    ${isProcessing ? 'bg-slate-400 cursor-wait' : 'bg-emerald-600 hover:bg-emerald-700 text-white'}
                `}
            >
                {isProcessing ? '正在处理...' : '选择图片文件'}
            </label>
        </div>
      )}

      {step === 2 && (
        <div className="grid lg:grid-cols-3 gap-8 items-start">
            {/* Left: Canvas */}
            <div className="lg:col-span-2 bg-slate-900 rounded-xl overflow-hidden shadow-lg relative min-h-[400px]" ref={containerRef}>
                <div className="absolute top-4 left-4 z-10 bg-black/60 backdrop-blur text-white text-xs px-3 py-1 rounded-full pointer-events-none">
                    {activeAnnotation 
                        ? `请在图中框选: ${samples.find(s => s.id === activeAnnotation.sampleId)?.name} - ${activeAnnotation.type === 'target' ? '目的蛋白' : '内参蛋白'}` 
                        : '请在右侧列表中点击按钮开始框选'}
                </div>
                <canvas 
                    ref={canvasRef}
                    onMouseDown={handleMouseDown}
                    onMouseMove={handleMouseMove}
                    onMouseUp={handleMouseUp}
                    onMouseLeave={handleMouseUp}
                    className={`block w-full cursor-crosshair touch-none ${activeAnnotation ? 'cursor-crosshair' : 'cursor-default'}`}
                />
            </div>

            {/* Right: Controls */}
            <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-6 space-y-6 max-h-[calc(100vh-200px)] overflow-y-auto">
                <div>
                    <h3 className="font-bold text-slate-800 mb-4 flex items-center justify-between">
                        样本列表
                        <button onClick={addSample} className="text-emerald-600 hover:bg-emerald-50 p-1 rounded transition-colors">
                            <Plus size={20} />
                        </button>
                    </h3>

                    <div className="space-y-4">
                        {samples.map((sample) => (
                            <div key={sample.id} className="bg-slate-50 rounded-lg p-3 border border-slate-100 transition-all hover:border-emerald-200">
                                <div className="flex items-center gap-2 mb-3">
                                    <input 
                                        type="radio" 
                                        name="controlGroup" 
                                        checked={sample.isControl} 
                                        onChange={() => setControlSample(sample.id)}
                                        className="text-emerald-500 focus:ring-emerald-500"
                                        title="设为对照组 (Control)"
                                    />
                                    <input 
                                        type="text" 
                                        value={sample.name} 
                                        onChange={(e) => updateSampleName(sample.id, e.target.value)}
                                        className="bg-transparent border-b border-transparent hover:border-slate-300 focus:border-emerald-500 outline-none text-sm font-medium text-slate-700 w-full"
                                    />
                                    <button onClick={() => removeSample(sample.id)} className="text-slate-400 hover:text-red-500">
                                        <Trash2 size={14} />
                                    </button>
                                </div>

                                <div className="grid grid-cols-2 gap-2">
                                    <button 
                                        onClick={() => setActiveAnnotation({ sampleId: sample.id, type: 'target' })}
                                        className={`
                                            px-2 py-2 rounded text-xs font-medium flex items-center justify-center gap-1 border transition-all
                                            ${sample.targetRoi ? 'bg-blue-50 border-blue-200 text-blue-700' : 'bg-white border-slate-200 text-slate-500 hover:border-blue-300'}
                                            ${activeAnnotation?.sampleId === sample.id && activeAnnotation.type === 'target' ? 'ring-2 ring-blue-500 ring-offset-1' : ''}
                                        `}
                                    >
                                        {sample.targetRoi ? <Check size={12} /> : <Maximize size={12} />}
                                        目的蛋白
                                    </button>
                                    <button 
                                         onClick={() => setActiveAnnotation({ sampleId: sample.id, type: 'ref' })}
                                         className={`
                                            px-2 py-2 rounded text-xs font-medium flex items-center justify-center gap-1 border transition-all
                                            ${sample.refRoi ? 'bg-emerald-50 border-emerald-200 text-emerald-700' : 'bg-white border-slate-200 text-slate-500 hover:border-emerald-300'}
                                            ${activeAnnotation?.sampleId === sample.id && activeAnnotation.type === 'ref' ? 'ring-2 ring-emerald-500 ring-offset-1' : ''}
                                        `}
                                    >
                                        {sample.refRoi ? <Check size={12} /> : <Maximize size={12} />}
                                        内参蛋白
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="pt-4 border-t border-slate-100">
                    <button 
                        onClick={performAnalysis}
                        disabled={samples.some(s => !s.targetRoi || !s.refRoi)}
                        className="w-full bg-emerald-600 hover:bg-emerald-700 disabled:bg-slate-300 disabled:cursor-not-allowed text-white py-3 rounded-lg font-bold shadow-lg shadow-emerald-500/20 transition-all active:scale-95 flex items-center justify-center gap-2"
                    >
                        <BarChart3 size={20} />
                        开始分析
                    </button>
                    {samples.some(s => !s.targetRoi || !s.refRoi) && (
                        <p className="text-xs text-center text-slate-400 mt-2">请标记所有样本的条带区域</p>
                    )}
                </div>
            </div>
        </div>
      )}

      {step === 3 && (
        <div className="space-y-8">
            <div className="flex items-center justify-between bg-white p-4 rounded-xl shadow-sm border border-slate-200">
                 <h3 className="text-lg font-bold text-slate-800">分析结果</h3>
                 <div className="flex gap-2">
                     <button 
                        onClick={() => setStep(2)} 
                        className="px-4 py-2 text-slate-600 hover:bg-slate-50 rounded-lg text-sm font-medium transition-colors"
                     >
                        调整选区
                     </button>
                     <button 
                        onClick={() => { setStep(1); setSamples([{ id: '1', name: 'Control', isControl: true }]); setImageSrc(null); }} 
                        className="px-4 py-2 bg-slate-800 hover:bg-slate-900 text-white rounded-lg text-sm font-medium flex items-center gap-2"
                     >
                        <RotateCcw size={16} /> 重新开始
                     </button>
                 </div>
            </div>

            <div className="grid md:grid-cols-2 gap-8">
                {/* Chart */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6">
                    <h4 className="font-bold text-slate-700 mb-6 pl-2 border-l-4 border-emerald-500">相对表达量 (Normalized to Control)</h4>
                    <div className="h-[300px] w-full">
                        <ResponsiveContainer width="100%" height="100%">
                             <BarChart data={chartData} margin={{ top: 20, right: 30, left: 20, bottom: 5 }}>
                                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e2e8f0" />
                                <XAxis dataKey="name" axisLine={false} tickLine={false} tick={{ fill: '#64748b' }} dy={10} />
                                <YAxis axisLine={false} tickLine={false} tick={{ fill: '#64748b' }} />
                                <Tooltip cursor={{ fill: '#f1f5f9' }} contentStyle={{ borderRadius: '8px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }} />
                                <Bar dataKey="expression" fill="#10b981" radius={[6, 6, 0, 0]} name="Relative Expression" />
                             </BarChart>
                        </ResponsiveContainer>
                    </div>
                </div>

                {/* Table */}
                <div className="bg-white rounded-2xl shadow-sm border border-slate-200 p-6 overflow-hidden">
                    <h4 className="font-bold text-slate-700 mb-6 pl-2 border-l-4 border-blue-500">详细数据</h4>
                    <div className="overflow-x-auto">
                        <table className="w-full text-sm text-left">
                            <thead className="bg-slate-50 text-slate-500 font-medium">
                                <tr>
                                    <th className="px-3 py-2 rounded-l-lg">样本</th>
                                    <th className="px-3 py-2 text-right">Raw (Target)</th>
                                    <th className="px-3 py-2 text-right">Raw (Ref)</th>
                                    <th className="px-3 py-2 text-right">Ratio (T/R)</th>
                                    <th className="px-3 py-2 text-right rounded-r-lg">Rel. Exp.</th>
                                </tr>
                            </thead>
                            <tbody className="divide-y divide-slate-100">
                                {samples.map(s => (
                                    <tr key={s.id} className="hover:bg-slate-50">
                                        <td className="px-3 py-3 font-medium text-slate-700">
                                            {s.name} {s.isControl && <span className="text-xs bg-slate-100 text-slate-400 px-1.5 rounded ml-1">Ctrl</span>}
                                        </td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono">{Math.round(s.targetDensity || 0).toLocaleString()}</td>
                                        <td className="px-3 py-3 text-right text-slate-500 font-mono">{Math.round(s.refDensity || 0).toLocaleString()}</td>
                                        <td className="px-3 py-3 text-right text-blue-600 font-mono">{(s.normalizedRatio || 0).toFixed(3)}</td>
                                        <td className="px-3 py-3 text-right font-bold text-emerald-600 font-mono">{(s.relativeExpression || 0).toFixed(2)}</td>
                                    </tr>
                                ))}
                            </tbody>
                        </table>
                    </div>
                </div>
            </div>

            <div className="bg-amber-50 border border-amber-100 rounded-xl p-4 flex items-start gap-3 text-sm text-amber-800">
                <AlertCircle className="shrink-0 mt-0.5 text-amber-500" size={18} />
                <p>
                    <strong>注意：</strong> 本工具使用简单的 "Integrated Density (Sum of Inverted Gray Value)" 算法。
                    为保证结果准确，建议上传背景干净的图片。如果背景噪音较大，结果可能会受到影响。
                    灰度计算公式: Density = Σ (255 - (0.299R + 0.587G + 0.114B))。
                </p>
            </div>
        </div>
      )}
    </div>
  );
};

import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Upload, Plus, Trash2, Maximize, Check, BarChart3, AlertCircle, RotateCcw, Activity, Image as ImageIcon, X } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
// @ts-ignore
import UTIF from 'utif';

// --- Types ---

interface WbImage {
  id: string;
  src: string;
  name: string;
}

interface Roi {
  imageId: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

interface WbSample {
  id: string;
  name: string;
  isControl: boolean;
  targetRoi?: Roi;
  refRoi?: Roi;
  // Computed values
  targetDensity?: number;
  refDensity?: number;
  normalizedRatio?: number; // Target / Ref
  relativeExpression?: number; // Ratio / Control_Ratio
}

// --- Helper Functions ---

const calculateDensityFromImage = (
  img: HTMLImageElement,
  roi: Roi
): number => {
  if (roi.w <= 0 || roi.h <= 0) return 0;

  const canvas = document.createElement('canvas');
  canvas.width = roi.w;
  canvas.height = roi.h;
  const ctx = canvas.getContext('2d');
  if (!ctx) return 0;

  // Draw only the ROI part of the image
  ctx.drawImage(img, -roi.x, -roi.y);

  const imageData = ctx.getImageData(0, 0, roi.w, roi.h);
  const data = imageData.data;
  let totalDensity = 0;

  for (let i = 0; i < data.length; i += 4) {
    const r = data[i];
    const g = data[i + 1];
    const b = data[i + 2];
    // Simple luminance conversion
    const gray = 0.299 * r + 0.587 * g + 0.114 * b;
    // Invert because bands are dark on white background
    const density = 255 - gray;
    totalDensity += density;
  }

  return totalDensity;
};

// --- Main Component ---

export const WesternTool: React.FC = () => {
  const [step, setStep] = useState<1 | 2 | 3>(1);
  const [wbImages, setWbImages] = useState<WbImage[]>([]);
  const [activeImageId, setActiveImageId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Samples State
  const [samples, setSamples] = useState<WbSample[]>([
    { id: '1', name: 'Control', isControl: true },
    { id: '2', name: 'Sample 1', isControl: false },
    { id: '3', name: 'Sample 2', isControl: false },
  ]);

  // Annotation State
  const [activeAnnotation, setActiveAnnotation] = useState<{ sampleId: string; type: 'target' | 'ref' } | null>(null);

  // Canvas Refs
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const imageCacheRef = useRef<Map<string, HTMLImageElement>>(new Map());

  // Dragging State for Drawing
  const [isDrawing, setIsDrawing] = useState(false);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [currentRect, setCurrentRect] = useState<Roi | null>(null);

  // --- Step 1: Logic (Upload) ---

  const processFile = async (file: File): Promise<WbImage | null> => {
     // Check for TIFF
    const isTiff = file.type === 'image/tiff' || file.name.toLowerCase().endsWith('.tif') || file.name.toLowerCase().endsWith('.tiff');
    let src = '';

    if (isTiff) {
        try {
            const buffer = await file.arrayBuffer();
            const ifds = UTIF.decode(buffer);
            if (ifds && ifds.length > 0) {
                const page = ifds[0];
                UTIF.decodeImage(buffer, page);
                const rgba = UTIF.toRGBA8(page);
                const canvas = document.createElement('canvas');
                canvas.width = page.width;
                canvas.height = page.height;
                const ctx = canvas.getContext('2d');
                if (ctx) {
                    const imageData = new ImageData(new Uint8ClampedArray(rgba.buffer), page.width, page.height);
                    ctx.putImageData(imageData, 0, 0);
                    src = canvas.toDataURL('image/png');
                }
            }
        } catch (err) {
            console.error("TIFF Error", err);
            return null;
        }
    } else {
        src = await new Promise((resolve) => {
            const reader = new FileReader();
            reader.onload = (e) => resolve(e.target?.result as string);
            reader.readAsDataURL(file);
        });
    }

    if (src) {
        return {
            id: Math.random().toString(36).substr(2, 9),
            name: file.name,
            src
        };
    }
    return null;
  };

  const handleImageUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;

    setIsProcessing(true);
    const newImages: WbImage[] = [];

    for (let i = 0; i < files.length; i++) {
        const img = await processFile(files[i]);
        if (img) newImages.push(img);
    }

    if (newImages.length > 0) {
        setWbImages(prev => [...prev, ...newImages]);
        if (!activeImageId) {
            setActiveImageId(newImages[0].id);
        }
    } else {
        alert("无法处理所选文件。");
    }

    setIsProcessing(false);
    // Reset input
    e.target.value = '';
  };

  const removeImage = (id: string) => {
      setWbImages(prev => prev.filter(img => img.id !== id));

      // Remove ROIs associated with this image
      setSamples(prev => prev.map(s => ({
          ...s,
          targetRoi: s.targetRoi?.imageId === id ? undefined : s.targetRoi,
          refRoi: s.refRoi?.imageId === id ? undefined : s.refRoi,
      })));

      if (activeImageId === id) {
          setActiveImageId(null);
      }

      imageCacheRef.current.delete(id);
  };

  const addSample = () => {
    const newId = (samples.length + 1).toString();
    setSamples([...samples, { id: newId, name: `Sample ${samples.length}`, isControl: false }]);
  };

  const removeSample = (id: string) => {
    if (samples.length <= 1) return;
    setSamples(samples.filter(s => s.id !== id));
  };

  const updateSampleName = (id: string, name: string) => {
    setSamples(samples.map(s => s.id === id ? { ...s, name } : s));
  };

  const setControlSample = (id: string) => {
    setSamples(samples.map(s => ({ ...s, isControl: s.id === id })));
  };

  // --- Step 2: Logic (Annotation) ---

  // Preload images into cache when step 2 starts or images change
  useEffect(() => {
      wbImages.forEach(imgData => {
          if (!imageCacheRef.current.has(imgData.id)) {
              const img = new Image();
              img.src = imgData.src;
              img.onload = () => { /* Loaded */ };
              imageCacheRef.current.set(imgData.id, img);
          }
      });
  }, [wbImages]);

  // Set default active image if needed
  useEffect(() => {
      if (step === 2 && !activeImageId && wbImages.length > 0) {
          setActiveImageId(wbImages[0].id);
      }
  }, [step, wbImages, activeImageId]);


  // Draw Canvas
  useEffect(() => {
    if (step === 2 && activeImageId && canvasRef.current && containerRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const img = imageCacheRef.current.get(activeImageId);

      if (img && img.complete && ctx) {
        // Fit image to container width
        const containerWidth = containerRef.current?.clientWidth || 800;

        canvas.width = img.width;
        canvas.height = img.height;

        // CSS scaling
        canvas.style.width = '100%';
        canvas.style.height = 'auto';

        ctx.drawImage(img, 0, 0);
        drawOverlays(ctx);
      } else if (img) {
          img.onload = () => {
             // Redraw when loaded
             if (canvasRef.current && containerRef.current && activeImageId === img.src) { // logic check needed here but basic redraw works
                 // Trigger re-render effectively
             }
          }
      }
    }
  }, [step, activeImageId, samples, currentRect, activeAnnotation, wbImages]); // Dependency on samples/rect ensures redraw on changes

  const drawOverlays = (ctx: CanvasRenderingContext2D) => {
    if (!activeImageId) return;

    // Draw saved ROIs that belong to CURRENT active image
    samples.forEach(sample => {
      if (sample.targetRoi && sample.targetRoi.imageId === activeImageId) {
          drawRoi(ctx, sample.targetRoi, '#3b82f6', 'T'); 
      }
      if (sample.refRoi && sample.refRoi.imageId === activeImageId) {
          drawRoi(ctx, sample.refRoi, '#10b981', 'R');
      }
    });

    // Draw current dragging rect
    if (currentRect && activeAnnotation) {
       const color = activeAnnotation.type === 'target' ? '#3b82f6' : '#10b981';
       drawRoi(ctx, currentRect, color, '', true);
    }
  };

  const drawRoi = (ctx: CanvasRenderingContext2D, roi: Roi, color: string, label: string, isDashed = false) => {
    ctx.beginPath();
    ctx.lineWidth = 4;
    ctx.strokeStyle = color;
    if (isDashed) ctx.setLineDash([6, 3]);
    else ctx.setLineDash([]);
    ctx.rect(roi.x, roi.y, roi.w, roi.h);
    ctx.stroke();

    ctx.fillStyle = color + '33'; // 20% opacity
    ctx.fill();

    if (label) {
        ctx.fillStyle = color;
        ctx.font = 'bold 32px Arial'; // Larger font for high res images
        ctx.fillText(label, roi.x, roi.y - 10);
    }
  };

  const getCanvasCoordinates = (e: React.MouseEvent) => {
    const canvas = canvasRef.current;
    if (!canvas) return { x: 0, y: 0 };
    const rect = canvas.getBoundingClientRect();
    const scaleX = canvas.width / rect.width;
    const scaleY = canvas.height / rect.height;
    return {
      x: (e.clientX - rect.left) * scaleX,
      y: (e.clientY - rect.top) * scaleY
    };
  };

  const handleMouseDown = (e: React.MouseEvent) => {
    if (!activeAnnotation || !activeImageId) return;
    setIsDrawing(true);
    const pos = getCanvasCoordinates(e);
    setStartPos(pos);
    setCurrentRect({ imageId: activeImageId, x: pos.x, y: pos.y, w: 0, h: 0 });
  };

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!isDrawing || !activeAnnotation || !activeImageId) return;
    const pos = getCanvasCoordinates(e);
    setCurrentRect({
      imageId: activeImageId,
      x: Math.min(startPos.x, pos.x),
      y: Math.min(startPos.y, pos.y),
      w: Math.abs(pos.x - startPos.x),
      h: Math.abs(pos.y - startPos.y)
    });
  };

  const handleMouseUp = () => {
    if (!isDrawing || !activeAnnotation || !currentRect) return;
    setIsDrawing(false);

    const updatedSamples = samples.map(s => {
      if (s.id === activeAnnotation.sampleId) {
        return {
          ...s,
          [activeAnnotation.type === 'target' ? 'targetRoi' : 'refRoi']: currentRect
        };
      }
      return s;
    });

    setSamples(updatedSamples);
    setCurrentRect(null);
    setActiveAnnotation(null);
  };

  // --- Step 3: Analysis ---

  const performAnalysis = () => {
    // 1. Calculate Raw Densities using cached images
    const rawResults = samples.map(s => {
        let targetDensity = 0;
        let refDensity = 0;

        if (s.targetRoi) {
            const img = imageCacheRef.current.get(s.targetRoi.imageId);
            if (img) targetDensity = calculateDensityFromImage(img, s.targetRoi);
        }

        if (s.refRoi) {
            const img = imageCacheRef.current.get(s.refRoi.imageId);
            if (img) refDensity = calculateDensityFromImage(img, s.refRoi);
        }

        return {
            ...s,
            targetDensity,
            refDensity
        };
    });

    // 2. Normalize
    const normalizedResults = rawResults.map(s => ({
        ...s,
        normalizedRatio: (s.targetDensity && s.refDensity) ? (s.targetDensity / s.refDensity) : 0
    }));

    const controlSample = normalizedResults.find(s => s.isControl);
    const controlRatio = controlSample?.normalizedRatio || 1;

    const finalResults = normalizedResults.map(s => ({
        ...s,
        relativeExpression: s.normalizedRatio / (controlRatio || 1)
    }));

    setSamples(finalResults);
    setStep(3);
  };

  // --- Render Helpers ---

  const chartData = useMemo(() => {
    return samples.map(s => ({
      name: s.name,
      expression: parseFloat((s.relativeExpression || 0).toFixed(2)),
      rawT: Math.round(s.targetDensity || 0),
      rawR: Math.round(s.refDensity || 0),
    }));
  }, [samples]);

  // --- View ---

  return (
    <div className="w-full animate-fade-in max-w-7xl mx-auto">

      {/* Header */}
      <div className="mb-8">
        <h2 className="text-2xl font-bold text-slate-800 flex items-center gap-2">
            <Activity className="text-emerald-500" />
