                        <button onClick={() => setStep(1)} title="Add Image" className="px-2 py-1.5 rounded-md text-slate-400 hover:bg-slate-100"><Plus size={16} /></button>
                    </div>

                    <div className="flex items-center gap-1 border-l border-slate-200 pl-2">
                        <button 
