                           <button onClick={addSample} className="px-3 py-1.5 bg-slate-100 hover:bg-slate-200 text-slate-600 rounded-lg text-sm font-medium transition-colors flex items-center gap-1">
                               <Plus size={16} /> 添加行
                           </button>
                       </div>
