                       </table>
                       {computedSamples.length === 0 && (
                           <div className="p-8 text-center text-slate-400 text-sm border-t border-slate-100 flex flex-col items-center gap-2">
                               <Clipboard size={32} className="opacity-20" />
                               <p>在此处粘贴 Excel 数据 (Ctrl+V)</p>
