                                       <td className="py-2 font-medium text-slate-700 max-w-[80px] truncate" title={img.name}>{img.name}</td>
                                       <td className="py-2 text-right text-slate-500">
                                           {img.positiveCount || 0} / {img.totalCount || 0}
