import React, { useState, useMemo } from 'react';
import { PawPrint, Calculator, FlaskConical, Syringe, Plus, Trash2, Save, Download, Shuffle, Users } from 'lucide-react';

interface DosingGroup {
  id: string;
  name: string;
  count: number;
  weight: number; // g for small animals
  dosage: number; // mg/kg
  adminVolume: number; // mL/kg
}

const DEFAULT_GROUP: DosingGroup = {
  id: '',
  name: 'Group 1',
  count: 6,
  weight: 20, // Mouse default
  dosage: 10,
  adminVolume: 10 // 10 mL/kg
};

export const AnimalExperimentTool: React.FC = () => {
  const [activeTab, setActiveTab] = useState<'dosing' | 'randomization'>('dosing');

  // --- Dosing Calculator State ---
  const [groups, setGroups] = useState<DosingGroup[]>([{...DEFAULT_GROUP, id: '1'}]);
  const [animalType, setAnimalType] = useState<'mouse' | 'rat'>('mouse');
  const [safetyMargin, setSafetyMargin] = useState<number>(20); // %

  // Handlers
  const addGroup = () => {
    setGroups(prev => [
      ...prev, 
      {
        ...DEFAULT_GROUP, 
        id: Date.now().toString(), 
        name: `Group ${prev.length + 1}`,
        weight: animalType === 'mouse' ? 20 : 200,
        adminVolume: animalType === 'mouse' ? 10 : 5
      }
    ]);
  };

  const updateGroup = (id: string, field: keyof DosingGroup, value: string | number) => {
    setGroups(prev => prev.map(g => {
      if (g.id !== id) return g;
      return { ...g, [field]: value };
    }));
  };

  const removeGroup = (id: string) => {
    if (groups.length > 1) {
      setGroups(prev => prev.filter(g => g.id !== id));
    }
  };

  const handleAnimalTypeChange = (type: 'mouse' | 'rat') => {
    setAnimalType(type);
    // Update defaults for existing groups if they match typical values of the other type
    // Or just let user adjust manually. Here we force update defaults for new UX.
    const defaultWeight = type === 'mouse' ? 20 : 200;
    const defaultVol = type === 'mouse' ? 10 : 5;

    setGroups(prev => prev.map(g => ({
        ...g,
        weight: defaultWeight,
        adminVolume: defaultVol
    })));
  };

  // Calculations
  const calculatedData = useMemo(() => {
    let totalAnimals = 0;
    let totalDrugMg = 0; // Raw sum

    const groupResults = groups.map(g => {
        // Conc (mg/mL) = Dosage (mg/kg) / AdminVol (mL/kg)
        const concentration = g.dosage / g.adminVolume;

        // Single Dose (mg) = Weight (kg) * Dosage (mg/kg)
        const weightKg = g.weight / 1000;
        const dosePerAnimal = weightKg * g.dosage;

        // Single Vol (mL) = Weight (kg) * AdminVol (mL/kg)
        const volPerAnimal = weightKg * g.adminVolume;

        // Total Volume Needed (mL) = VolPerAnimal * Count * (1 + Margin)
        const totalVol = volPerAnimal * g.count * (1 + safetyMargin / 100);

        // Total Drug Needed (mg) = TotalVol * Concentration
        const totalDrug = totalVol * concentration;

        return {
            ...g,
            concentration,
            dosePerAnimal,
            volPerAnimal,
            totalVol,
            totalDrug
        };
    });

    return groupResults;
  }, [groups, safetyMargin]);

  const handleExportCsv = () => {
      let csv = "\uFEFFGroup,Count,Weight(g),Dosage(mg/kg),Admin Vol(mL/kg),Conc(mg/mL),Vol/Animal(mL),Total Prep Vol(mL),Total Drug(mg)\n";
      calculatedData.forEach(g => {
          csv += `"${g.name}",${g.count},${g.weight},${g.dosage},${g.adminVolume},${g.concentration.toFixed(2)},${g.volPerAnimal.toFixed(3)},${g.totalVol.toFixed(2)},${g.totalDrug.toFixed(2)}\n`;
      });
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "Animal_Dosing_Plan.csv";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in">
       {/* Header */}
       <div className="flex items-center gap-4 mb-2">
           <div className="bg-amber-100 p-3 rounded-2xl text-amber-800">
                <PawPrint size={32} />
           </div>
           <div>
               <h2 className="text-2xl font-bold text-slate-800">动物实验设计</h2>
               <p className="text-slate-500">集成给药方案计算、随机分组等工具</p>
           </div>
       </div>

