                                    <div className="mt-2 pt-2 text-[10px] text-slate-400 bg-slate-50 p-2 rounded">
                                        * 请按顺序加入溶剂，每一步充分涡旋混匀。对于难溶药物，可适当超声或加热。
                                    </div>
                                </div>
                            </div>
                        ))}
                   </div>
               </div>

           </div>
       </div>
    </div>
  );
};

