                        <button onClick={applyUniformSize} className="text-xs bg-white border border-slate-300 hover:bg-slate-50 px-3 py-1.5 rounded-md font-medium flex items-center gap-1 ml-auto" title="将当前图像上的所有选区大小调整为与当前选中选区一致">
