import React, { useState, useRef, useEffect, useCallback, useMemo } from 'react';
import { Network, Upload, Trash2, Sliders, Play, RefreshCw, Eye, Download, Info, BarChart3, GitBranch, Zap } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ErrorBar, Cell } from 'recharts';
import { processImageFile } from '../../services/imageUtils';

// --- Types ---

interface AngioImage {
  id: string;
  name: string;
  group: string;
  src: string;

  // Metrics
  totalLength: number | null; // px
  junctions: number | null;
  endpoints: number | null;
  meshes: number | null; // loops

  // Visualization Data
  skeleton: Uint8Array | null; // Flattened binary array (0 or 1)
  width: number;
  height: number;

  processed: boolean;
}

interface ProcessSettings {
  threshold: number; // 0-255
  invert: boolean; // True for dark tubes on bright bg (Phase contrast), False for fluorescence
  minPathSize: number; // Pruning small artifacts
}

// --- Algorithms ---

// 1. Zhang-Suen Thinning Algorithm
// Reduces binary shapes to 1-pixel wide skeletons
const thinningZhangSuen = (data: Uint8Array, width: number, height: number): Uint8Array => {
    const skeleton = new Uint8Array(data); // Copy
    let changing = true;

    const getPixel = (arr: Uint8Array, x: number, y: number) => {
        if (x < 0 || x >= width || y < 0 || y >= height) return 0;
        return arr[y * width + x];
    };

    const setPixel = (arr: Uint8Array, x: number, y: number, val: number) => {
        arr[y * width + x] = val;
    };

    while (changing) {
        changing = false;
        // Two sub-iterations
        for (let sub = 0; sub < 2; sub++) {
            const markers: number[] = [];
            for (let y = 1; y < height - 1; y++) {
                for (let x = 1; x < width - 1; x++) {
                    if (getPixel(skeleton, x, y) === 0) continue;

                    // Get 8 neighbors: P2, P3, ... P9
                    // P9 P2 P3
                    // P8 P1 P4
                    // P7 P6 P5
                    const p2 = getPixel(skeleton, x, y - 1);
                    const p3 = getPixel(skeleton, x + 1, y - 1);
                    const p4 = getPixel(skeleton, x + 1, y);
                    const p5 = getPixel(skeleton, x + 1, y + 1);
                    const p6 = getPixel(skeleton, x, y + 1);
                    const p7 = getPixel(skeleton, x - 1, y + 1);
                    const p8 = getPixel(skeleton, x - 1, y);
                    const p9 = getPixel(skeleton, x - 1, y - 1);

                    const A = (p2 === 0 && p3 === 1 ? 1 : 0) +
                              (p3 === 0 && p4 === 1 ? 1 : 0) +
                              (p4 === 0 && p5 === 1 ? 1 : 0) +
                              (p5 === 0 && p6 === 1 ? 1 : 0) +
                              (p6 === 0 && p7 === 1 ? 1 : 0) +
                              (p7 === 0 && p8 === 1 ? 1 : 0) +
                              (p8 === 0 && p9 === 1 ? 1 : 0) +
                              (p9 === 0 && p2 === 1 ? 1 : 0);

                    const B = p2 + p3 + p4 + p5 + p6 + p7 + p8 + p9;

                    let m1, m2;
                    if (sub === 0) {
                        m1 = p2 * p4 * p6;
                        m2 = p4 * p6 * p8;
                    } else {
                        m1 = p2 * p4 * p8;
                        m2 = p2 * p6 * p8;
                    }

                    if (A === 1 && (B >= 2 && B <= 6) && m1 === 0 && m2 === 0) {
                        markers.push(y * width + x);
                    }
                }
            }
            if (markers.length > 0) {
                changing = true;
                for (const idx of markers) skeleton[idx] = 0;
            }
        }
    }
    return skeleton;
};

// 2. Analyze Graph
const analyzeSkeleton = (skeleton: Uint8Array, width: number, height: number, minPathSize: number) => {
    let totalLength = 0;
    let junctions = 0;
    let endpoints = 0;

    // Iterate to find junctions and endpoints
    // Also Pruning could happen here, but for simplicity we rely on minPathSize later or Pre-filtering
    // Simple pixel counting first

    for (let y = 1; y < height - 1; y++) {
        for (let x = 1; x < width - 1; x++) {
            if (skeleton[y * width + x] === 1) {
                totalLength++;

                // Count neighbors
                let neighbors = 0;
                for(let dy = -1; dy <= 1; dy++) {
                    for(let dx = -1; dx <= 1; dx++) {
                        if (dx === 0 && dy === 0) continue;
                        if (skeleton[(y + dy) * width + (x + dx)] === 1) neighbors++;
                    }
                }

                if (neighbors === 1) endpoints++;
                if (neighbors > 2) junctions++;
            }
        }
    }

    // 3. Count Meshes (Loops) via Connected Components of Background
    // Invert skeleton: 0->1 (bg), 1->0 (skeleton)
    // Label components. Count - 1 (outer bg) = Meshes
    const visited = new Uint8Array(width * height);
    let bgComponents = 0;

    for(let i=0; i<width*height; i++) {
        // If it's background (skeleton=0) and not visited
        if (skeleton[i] === 0 && visited[i] === 0) {
            bgComponents++;
            // BFS flood fill
            const stack = [i];
            visited[i] = 1;
            while(stack.length > 0) {
                const idx = stack.pop()!;
                const cx = idx % width;
                const cy = Math.floor(idx / width);

                // 4-connectivity is enough for background separation
                const neighbors = [
                    idx - 1, idx + 1, idx - width, idx + width
                ];

                // Check bounds for neighbors roughly (simplified)
                if (cx > 0 && skeleton[idx - 1] === 0 && visited[idx - 1] === 0) { visited[idx - 1] = 1; stack.push(idx - 1); }
                if (cx < width - 1 && skeleton[idx + 1] === 0 && visited[idx + 1] === 0) { visited[idx + 1] = 1; stack.push(idx + 1); }
                if (cy > 0 && skeleton[idx - width] === 0 && visited[idx - width] === 0) { visited[idx - width] = 1; stack.push(idx - width); }
                if (cy < height - 1 && skeleton[idx + width] === 0 && visited[idx + width] === 0) { visited[idx + width] = 1; stack.push(idx + width); }
            }
        }
    }

    // Meshes = Background Components - 1 (The infinite outside)
    const meshes = Math.max(0, bgComponents - 1);

    return { totalLength, junctions, endpoints, meshes };
};

const processImage = (img: HTMLImageElement, settings: ProcessSettings) => {
    // 1. Prepare Canvas (Downscale for performance if huge)
    const MAX_DIM = 800;
    let w = img.width;
    let h = img.height;
    if (w > MAX_DIM || h > MAX_DIM) {
        const scale = MAX_DIM / Math.max(w, h);
        w = Math.floor(w * scale);
        h = Math.floor(h * scale);
    }

    const canvas = document.createElement('canvas');
    canvas.width = w;
    canvas.height = h;
    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error("Canvas init failed");

    ctx.drawImage(img, 0, 0, w, h);
    const imgData = ctx.getImageData(0, 0, w, h);
    const src = imgData.data;

    // 2. Binarize
    const binary = new Uint8Array(w * h);
    for (let i = 0; i < src.length; i += 4) {
        // Luminance
        const gray = 0.299 * src[i] + 0.587 * src[i+1] + 0.114 * src[i+2];
        const val = settings.invert 
            ? (gray < settings.threshold ? 1 : 0) // Dark tubes on bright bg (Phase Contrast)
            : (gray > settings.threshold ? 1 : 0); // Bright tubes on dark bg (Fluorescence)
        binary[i / 4] = val;
    }

    // 3. Filter Small Noise (Dust) - Optional simple pass before thinning
    // (Skipped for brevity, rely on thinning handling some noise or post-process)

    // 4. Skeletonize
    const skeleton = thinningZhangSuen(binary, w, h);

    // 5. Analyze
    const stats = analyzeSkeleton(skeleton, w, h, settings.minPathSize);

    return { ...stats, skeleton, width: w, height: h };
};


export const AngiogenesisTool: React.FC = () => {
  const [images, setImages] = useState<AngioImage[]>([]);
  const [activeImageId, setActiveImageId] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);

  // Settings
  const [settings, setSettings] = useState<ProcessSettings>({
    threshold: 120,
    invert: true, // Default to Phase Contrast (dark tubes)
    minPathSize: 5
  });

  const canvasRef = useRef<HTMLCanvasElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  // --- Handlers ---

  const handleUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files || files.length === 0) return;
    setIsProcessing(true);

    const newImages: AngioImage[] = [];
    for (let i = 0; i < files.length; i++) {
        const src = await processImageFile(files[i]);
        if (src) {
            newImages.push({
              id: Date.now() + i + Math.random().toString(),
              name: files[i].name,
              group: 'Group 1',
              src: src,
              totalLength: null,
              junctions: null,
              endpoints: null,
              meshes: null,
              skeleton: null,
              width: 0,
              height: 0,
              processed: false
            });
        }
    }
    setImages(prev => [...prev, ...newImages]);
    if (!activeImageId && newImages.length > 0) setActiveImageId(newImages[0].id);
    setIsProcessing(false);
    e.target.value = '';
  };

  const removeImage = (id: string) => {
    setImages(prev => prev.filter(img => img.id !== id));
    if (activeImageId === id) setActiveImageId(null);
  };

  const updateImageGroup = (id: string, group: string) => {
    setImages(prev => prev.map(img => img.id === id ? { ...img, group } : img));
  };

  // --- Analysis ---

  const analyzeActiveImage = useCallback(() => {
    if (!activeImageId) return;
    const imgData = images.find(i => i.id === activeImageId);
    if (!imgData) return;

    setIsProcessing(true);
    setTimeout(() => {
      const img = new Image();
      img.src = imgData.src;
      img.onload = () => {
        try {
            const result = processImage(img, settings);
            setImages(prev => prev.map(item => 
              item.id === activeImageId 
                ? { ...item, ...result, processed: true } 
                : item
            ));
        } catch(e) {
            console.error(e);
        } finally {
            setIsProcessing(false);
        }
      };
    }, 50);
  }, [activeImageId, images, settings]);

  const analyzeAll = () => {
    setIsProcessing(true);
    const processNext = (index: number) => {
        if (index >= images.length) {
            setIsProcessing(false);
            return;
        }
        const imgData = images[index];
        const img = new Image();
        img.src = imgData.src;
        img.onload = () => {
            const result = processImage(img, settings);
            setImages(prev => prev.map(item => 
                item.id === imgData.id 
                ? { ...item, ...result, processed: true } 
                : item
            ));
            setTimeout(() => processNext(index + 1), 10);
        };
    };
    processNext(0);
  };

  // --- Drawing ---

  useEffect(() => {
    if (!activeImageId || !canvasRef.current) return;
    const canvas = canvasRef.current;
    const ctx = canvas.getContext('2d');
    const imgData = images.find(i => i.id === activeImageId);

    if (!ctx || !imgData) return;

    const img = new Image();
    img.src = imgData.src;
    img.onload = () => {
        // We use the processed dimensions for canvas if available, else natural
        const w = imgData.width || img.width;
        const h = imgData.height || img.height;

        canvas.width = w;
        canvas.height = h;

        // Draw Original Scaled
        ctx.drawImage(img, 0, 0, w, h);

        // Overlay Skeleton
        if (imgData.processed && imgData.skeleton) {
            const skel = imgData.skeleton;
            const imageData = ctx.getImageData(0, 0, w, h);
            const data = imageData.data;

            // Draw skeleton in Red
            for(let i=0; i<w*h; i++) {
                if (skel[i] === 1) {
                    const idx = i * 4;
                    data[idx] = 255;   // R
                    data[idx+1] = 0;   // G
                    data[idx+2] = 0;   // B
                    data[idx+3] = 255; // A
                }
            }
            ctx.putImageData(imageData, 0, 0);

            // Draw Junctions (Blue) & Endpoints (Green) using simple neighbor check on canvas for vis
            // Ideally we should have stored these points in analysis, but recalculating for display is fast
            ctx.fillStyle = '#3b82f6'; // Blue Junctions
            for (let y = 1; y < h - 1; y++) {
                for (let x = 1; x < w - 1; x++) {
                    if (skel[y * w + x] === 1) {
                        let n = 0;
                        for(let dy=-1; dy<=1; dy++) 
                            for(let dx=-1; dx<=1; dx++) 
                                if((dx!==0||dy!==0) && skel[(y+dy)*w + (x+dx)] === 1) n++;

                        if (n > 2) ctx.fillRect(x-1, y-1, 3, 3);
                    }
                }
            }

            ctx.fillStyle = '#22c55e'; // Green Endpoints
            for (let y = 1; y < h - 1; y++) {
                for (let x = 1; x < w - 1; x++) {
                    if (skel[y * w + x] === 1) {
                        let n = 0;
                        for(let dy=-1; dy<=1; dy++) 
                            for(let dx=-1; dx<=1; dx++) 
                                if((dx!==0||dy!==0) && skel[(y+dy)*w + (x+dx)] === 1) n++;

                        if (n === 1) ctx.fillRect(x-1, y-1, 3, 3);
                    }
                }
            }
        }
    };
  }, [activeImageId, images]); 

  // --- Stats Export ---

  const groupStats = useMemo(() => {
      const groups: Record<string, { totalLen: number; junc: number; mesh: number; count: number }> = {};
      images.filter(i => i.processed).forEach(img => {
          if (!groups[img.group]) groups[img.group] = { totalLen: 0, junc: 0, mesh: 0, count: 0 };
          groups[img.group].totalLen += img.totalLength || 0;
          groups[img.group].junc += img.junctions || 0;
          groups[img.group].mesh += img.meshes || 0;
          groups[img.group].count++;
      });

      return Object.entries(groups).map(([name, stats]) => ({
          name,
          meanLen: parseFloat((stats.totalLen / stats.count).toFixed(0)),
          meanJunc: parseFloat((stats.junc / stats.count).toFixed(1)),
          meanMesh: parseFloat((stats.mesh / stats.count).toFixed(1))
      }));
  }, [images]);

  const handleExportCsv = () => {
    let csv = "\uFEFFGroup,Image Name,Total Length (px),Junctions,Endpoints,Meshes (Loops)\n";
    images.forEach(img => {
        csv += `"${img.group}","${img.name}",${img.totalLength || 0},${img.junctions || 0},${img.endpoints || 0},${img.meshes || 0}\n`;
    });
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "Angiogenesis_Results.csv";
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  return (
    <div className="max-w-7xl mx-auto space-y-6 animate-fade-in">
       {/* Header */}
       <div className="flex items-center gap-4 mb-2">
           <div className="bg-red-100 p-3 rounded-2xl text-red-600">
                <Network size={32} />
           </div>
