// --- Types ---

interface WbImage {
  id: string;
  src: string;
  name: string;
}

interface Roi {
  imageId: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

interface WbSample {
  id: string;
  name: string;
  group: string; // Added for biological replicates
  isControl: boolean;
  targetRoi?: Roi;
  refRoi?: Roi;
  // Computed values
  targetDensity?: number;
  refDensity?: number;
  normalizedRatio?: number; // Target / Ref
  relativeExpression?: number; // Ratio / Control_Ratio
}

interface HitResult {
  sampleId: string;
  type: 'target' | 'ref';
  handle: 'nw' | 'ne' | 'se' | 'sw' | 'center';
}

// History Snapshot
type HistoryState = WbSample[];

interface DragState {
  mode: 'none' | 'drawing' | 'moving' | 'resizing' | 'region_selecting';
  startPos: { x: number; y: number };
  // For moving/resizing/drawing samples
  targetSampleId?: string;
  targetRoiType?: 'target' | 'ref';
  initialRoi?: Roi;
  handle?: 'nw' | 'ne' | 'sw' | 'se';
  // For region selecting
