                           <div className="flex items-start justify-between">
                               <div>
                                   <div className="text-xs font-bold text-cyan-600 bg-cyan-50 px-2 py-1 rounded inline-block mb-2 uppercase tracking-wide">
                                       {selectedReagent.category}
