// --- Types ---

interface WbImage {
  id: string;
  src: string;
  name: string;
}

interface Roi {
  imageId: string;
  x: number;
  y: number;
  w: number;
  h: number;
}

interface WbSample {
  id: string;
  name: string;
  group: string; // Added for biological replicates
  isControl: boolean;
  targetRoi?: Roi;
  refRoi?: Roi;
  // Computed values
