// --- Types ---

interface HeatmapData {
  rows: string[]; // Row labels (e.g., Genes)
  cols: string[]; // Col labels (e.g., Samples)
  matrix: number[][]; // Raw values
}

type ColorPalette = 'rwb' | 'gbr' | 'viridis' | 'magma' | 'plasma' | 'blue' | 'red' | 'rainbow' | 'bgyr';

// --- Constants ---

