                    </div>
                    <div className="flex justify-end pt-4"><button onClick={() => setStep(2)} className="bg-slate-800 hover:bg-slate-900 text-white px-8 py-3 rounded-lg font-medium shadow-lg transition-all">下一步：框选条带</button></div>
                </div>
