                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 mb-2">下一次目标上样体积 (Target Volume)</label>
                                <div className="flex items-center gap-2">
                                    <input 
                                        type="number" 
                                        value={normConfig.targetVol}
                                        onChange={(e) => setNormConfig({...normConfig, targetVol: parseFloat(e.target.value) || 0})}
                                        className="flex-1 text-sm border border-slate-300 rounded-lg px-3 py-2 focus:border-cyan-500 outline-none"
                                    />
                                    <span className="text-sm text-slate-600">μL</span>
                                </div>
                                <p className="text-[10px] text-slate-400 mt-1">
                                    希望基准样本下一次跑胶时的体积
                                </p>
                            </div>

                            <div>
                                <label className="block text-xs font-bold text-slate-500 mb-2">对齐基准 (Reference Basis)</label>
                                <select 
                                    value={normConfig.strategy} 
                                    onChange={(e) => setNormConfig({...normConfig, strategy: e.target.value as NormStrategy})}
                                    className="w-full text-sm border border-slate-300 rounded-lg px-3 py-2 focus:ring-2 focus:ring-cyan-500 outline-none"
                                >
                                    <option value="mean">所有样本平均值 (Mean)</option>
                                    <option value="weakest">信号最弱的样本 (Weakest)</option>
                                    <option value="strongest">信号最强的样本 (Strongest)</option>
                                    <option value="manual">指定某个样本 (Manual)</option>
                                </select>
                            </div>

                            {normConfig.strategy === 'manual' && (
                                <div>
                                    <label className="block text-xs font-bold text-slate-500 mb-2">选择基准样本</label>
                                    <select 
                                        value={normConfig.manualRefId || ''}
                                        onChange={(e) => setNormConfig({...normConfig, manualRefId: e.target.value})}
                                        className="w-full text-sm border border-slate-300 rounded-lg px-3 py-2 bg-slate-50"
                                    >
                                        {samples.map((s) => (
                                            <option key={s.id} value={s.id}>{s.name} (Vol: {normConfig.currentVol}, Int: {Math.round(s.refDensity || 0)})</option>
                                        ))}
                                    </select>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* RIGHT: Results */}
                    <div className="lg:col-span-8 flex flex-col gap-6">
                        <div className="bg-white rounded-xl shadow-sm border border-slate-200 p-5">
                            <div className="flex justify-between items-center mb-4">
                                <h3 className="font-bold text-slate-800 flex items-center gap-2">
                                    <FlaskConical size={18} className="text-cyan-500" /> 调整方案
                                </h3>
                                <button onClick={handleNormExport} className="bg-slate-800 hover:bg-slate-900 text-white px-4 py-2 rounded-lg text-xs font-bold transition-colors flex items-center gap-2">
                                    <Download size={14} /> 导出 CSV
                                </button>
                            </div>

                            <div className="overflow-x-auto rounded-lg border border-slate-100">
                                <table className="w-full text-sm text-left">
                                    <thead className="bg-slate-50 text-slate-500 font-medium">
                                        <tr>
                                            <th className="px-4 py-3">样本名称</th>
                                            <th className="px-4 py-3 text-right">原始灰度 (Ref)</th>
                                            <th className="px-4 py-3 text-right">密度 (Int/uL)</th>
                                            <th className="px-4 py-3 text-right text-cyan-700 bg-cyan-50/50">新上样体积 (μL)</th>
                                            <th className="px-4 py-3 text-right">倍数变化</th>
                                        </tr>
                                    </thead>
                                    <tbody className="divide-y divide-slate-100">
                                        {normResults?.calculations.map((row) => (
                                            <tr key={row.id} className="hover:bg-slate-50">
                                                <td className="px-4 py-2 font-medium text-slate-700">
                                                    {row.name}
                                                </td>
                                                <td className="px-4 py-2 text-right text-slate-500">{Math.round(row.intensity)}</td>
                                                <td className="px-4 py-2 text-right text-slate-500">{row.densityPerVol.toFixed(1)}</td>
                                                <td className="px-4 py-2 text-right font-bold text-cyan-600 bg-cyan-50/30 text-lg">
                                                    {row.newVol.toFixed(2)}
                                                </td>
                                                <td className="px-4 py-2 text-right text-xs font-mono text-slate-400">
                                                    {normConfig.currentVol > 0 ? (row.newVol / normConfig.currentVol).toFixed(2) + 'x' : '-'}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
      )}
    </div>
  );
};

import React, { useState, useMemo, useRef, useCallback } from 'react';
import { Activity, Upload, Settings, RefreshCw, AlertCircle, FileText, Download, Play, TrendingUp, Clock } from 'lucide-react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, ReferenceArea, AreaChart, Area } from 'recharts';

// --- Types ---

interface EEGDataPoint {
  time: number;
  amplitude: number;
}

interface WindowResult {
  second: number;
  power: number;
  isSuppression: boolean;
}

interface TrendPoint {
  timeStart: number; // seconds
  timeEnd: number;
  label: string; // e.g. "0-2 min"
  bsr: number; // percentage 0-100
}

interface AnalysisResult {
  globalMeanPower: number;
  globalBsr: number; // 0-100
  totalSeconds: number;
  suppressionSeconds: number;
  windows: WindowResult[];
  trendData: TrendPoint[];
}

// --- Constants ---

const EPOCH_OPTIONS = [
    { value: 0, label: '全局 (Whole Recording)' },
    { value: 30, label: '30 秒 (30s Epochs)' },
    { value: 60, label: '1 分钟 (1 min Epochs)' },
    { value: 120, label: '2 分钟 (2 min Epochs)' },
    { value: 300, label: '5 分钟 (5 min Epochs)' },
];

// --- Helper: Downsample for Charting (Performance) ---
const downsampleData = (data: EEGDataPoint[], targetCount: number = 3000): EEGDataPoint[] => {
    if (data.length <= targetCount) return data;

    const sampled: EEGDataPoint[] = [];
    const step = Math.ceil(data.length / targetCount);

    for (let i = 0; i < data.length; i += step) {
        const chunk = data.slice(i, i + step);
        if (chunk.length === 0) break;

        let min = chunk[0], max = chunk[0];
        for (const p of chunk) {
            if (p.amplitude < min.amplitude) min = p;
            if (p.amplitude > max.amplitude) max = p;
        }
        if (min.time < max.time) {
            sampled.push(min, max);
        } else {
            sampled.push(max, min);
        }
    }
    return sampled.sort((a, b) => a.time - b.time);
};

export const BsrTool: React.FC = () => {
  const [rawData, setRawData] = useState<EEGDataPoint[]>([]);
  const [fileName, setFileName] = useState<string>('');

  // Parameters
  const [thresholdRatio, setThresholdRatio] = useState<number>(0.5); // Default 50%
  const [epochDuration, setEpochDuration] = useState<number>(60); // Default 1 min

  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState<AnalysisResult | null>(null);

  const fileInputRef = useRef<HTMLInputElement>(null);

  // --- Core Algorithm ---
  const analyzeSignal = useCallback(() => {
      if (rawData.length === 0) return;
      setIsProcessing(true);

      // Allow UI to render loading state
      setTimeout(() => {
          // 1. Calculate Global Mean Power (Mean of Squares)
          let sumSquares = 0;
          const n = rawData.length;

          // Group data into 1-second buckets
          const buckets: Record<number, number[]> = {};
          let maxTime = 0;

          for (let i = 0; i < n; i++) {
              const val = rawData[i].amplitude;
              const t = rawData[i].time;
              sumSquares += val * val;

              const sec = Math.floor(t);
              if (!buckets[sec]) buckets[sec] = [];
              buckets[sec].push(val);

              if (t > maxTime) maxTime = t;
          }

          const globalMeanPower = sumSquares / n;
          const powerThreshold = globalMeanPower * thresholdRatio;

          // 2. Window Analysis (1-second non-overlapping)
          const totalSeconds = Math.floor(maxTime) + 1;
          let globalSuppressionCount = 0;
          const windowResults: WindowResult[] = [];

          for (let s = 0; s < totalSeconds; s++) {
              const amps = buckets[s] || [];
              let wPower = 0;

              if (amps.length > 0) {
                  const wSumSq = amps.reduce((acc, val) => acc + val * val, 0);
                  wPower = wSumSq / amps.length;
              }

              // Determine State: Window Power < Ratio * Global Power
              const isSuppression = wPower < powerThreshold;
              if (isSuppression) globalSuppressionCount++;

              windowResults.push({
                  second: s,
                  power: wPower,
                  isSuppression
              });
          }

          // 3. Epoch/Trend Calculation
          const trendData: TrendPoint[] = [];

          if (epochDuration === 0) {
              // Global only
              trendData.push({
                  timeStart: 0,
                  timeEnd: totalSeconds,
                  label: "Global",
                  bsr: (globalSuppressionCount / totalSeconds) * 100
              });
          } else {
              // Sliding Epochs (Non-overlapping)
              for (let t = 0; t < totalSeconds; t += epochDuration) {
                  const end = Math.min(t + epochDuration, totalSeconds);
                  const duration = end - t;
                  if (duration === 0) break;

                  // Count suppression seconds in this slice
                  let localSuppression = 0;
                  for (let i = t; i < end; i++) {
                      if (windowResults[i]?.isSuppression) localSuppression++;
                  }

                  trendData.push({
                      timeStart: t,
                      timeEnd: end,
                      label: `${(t/60).toFixed(1)}-${(end/60).toFixed(1)}m`,
                      bsr: (localSuppression / duration) * 100
                  });
              }
          }

          setResult({
              globalMeanPower,
              globalBsr: (globalSuppressionCount / totalSeconds) * 100,
              totalSeconds,
              suppressionSeconds: globalSuppressionCount,
              windows: windowResults,
              trendData
          });

          setIsProcessing(false);
      }, 100);
  }, [rawData, thresholdRatio, epochDuration]);

  // --- File Handling ---
  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;

      setFileName(file.name);
      setIsProcessing(true);
      setResult(null);

      const reader = new FileReader();
      reader.onload = (event) => {
          const text = event.target?.result as string;
          const lines = text.trim().split(/[\r\n]+/);

          // Basic CSV Parsing
          const separator = lines[0].includes(',') ? ',' : '\t';
          let startRow = 0;
          if (/[a-zA-Z]/.test(lines[0])) startRow = 1;

          const parsedData: EEGDataPoint[] = [];

          for (let i = startRow; i < lines.length; i++) {
              const cols = lines[i].split(separator);
              if (cols.length >= 2) {
                  const t = parseFloat(cols[0]);
                  const v = parseFloat(cols[1]); 
                  if (!isNaN(t) && !isNaN(v)) {
                      parsedData.push({ time: t, amplitude: v });
                  }
              }
          }

          if (parsedData.length > 0) {
              parsedData.sort((a, b) => a.time - b.time);
              setRawData(parsedData);
          } else {
              alert("无法解析数据，请确保格式为：时间, 幅值 (CSV)");
          }
          setIsProcessing(false);
      };
      reader.readAsText(file);
  };

  // --- Export Data ---
